WordHunterWoW_QuestEN[43054] = { title = "An Ample Stockpile", description = "I have gone through our stockpile several times and no matter how I try to cut corners, we come up short.\n\nA lack of food and medicine will halt our war efforts... that is simply the reality.\n\nWe desperately need food or bandages. If you know how to acquire any such items, you can bring them to me.", objectives = "Turn in 100 Spiced Rib Roasts, Highmountain Salmon, or Silkweave Bandages for Lao Shu's stockpile. The Cooking and First Aid professions may be useful for this task.", completion = "Wonderful, yes yes! These supplies will fill our storehouse for weeks to come. Thank you so much, Grandmaster." }
WordHunterWoW_QuestEN[43055] = { title = "Candy Bucket", description = "", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!" }
