WordHunterWoW_QuestEN[43058] = { title = "Spiced Rib Roast", description = "", objectives = "Spiced Rib Roast is a light meal that can be made by those skilled in cooking. If you are not learned in this profession, you may be able to acquire the services of a cook elsewhere.", progress = "Spiced Rib Roast is a light meal that can be made by those skilled in cooking. If you are not learned in this profession, you may be able to acquire the services of a cook elsewhere.", completion = "Yes, these will do nicely. I'll get them salted and cured right away!" }
