WordHunterWoW_QuestEN[43060] = { title = "Highmountain Salmon", description = "", objectives = "This delicious fish can be found in the pools of Highmountain. Taking up fishing can be a productive and rewarding profession. Or, I hear there are plenty of fishers who are open to trading.", progress = "This delicious fish can be found in the pools of Highmountain. Taking up fishing can be a productive and rewarding profession. Or, I hear there are plenty of fishers who are open to trading.", completion = "What a beautiful catch! I've never seen fish this size! Thank you, Grand Master." }
WordHunterWoW_QuestEN[43061] = { title = "Silkweave Bandages", description = "", objectives = "Did you procure any bandages?", progress = "Did you procure any bandages?", completion = "These bandages will help save many lives. Thank you." }
WordHunterWoW_QuestEN[43062] = { title = "Further Training", description = "You may be the Grandmaster, but mastery must be maintained through discipline.\n\nTo achieve perfect harmony, you must continue your training.\n\nI would like to see your form in practice, {name}. Go out and use your Crackling Jade Lightning, Roll, and Blackout Kick or Blackout Strike. Through discipline, we find greatness.", objectives = "Use your Crackling Jade Lightning, Roll, and Blackout Kick or Blackout Strike abilities 10 times each.", progress = "To achieve mastery, we must hone ourselves tirelessly.", completion = "Very impressive indeed, <name>. I had no doubt that your form is still top notch." }
