WordHunterWoW_QuestEN[43100] = { title = "Finding the Scepter", description = "Very powerful, but difficult to acquire. Scepter is in the hands of Gul'dan. We must find out his plans, get close.\n\nCalydus know Gul'dan planning major operation. He has sent out a call to arms to all Shadow Council to help with big ritual. One such group at Caer Darrow, talking to the necromancers there.\n\nYou should go, find out about plan.", objectives = "Go to Caer Darrow in Western Plaguelands and find out about the Shadow Council ritual.", progress = "This gets complicated, but Calydus have idea!", completion = "Gul'dan says any of power may join. What if friend joined? Then when close take the Scepter and run!\n\nYes! Could work but must work hard to earn trust. Gul'dan still needs Eye. Friend should help with that, earn more respect." }
