WordHunterWoW_QuestEN[43151] = { title = "Making A Trade", description = "Yes I do have Amaranthine Hops, but they took me quite some time to gather. I cannot part with them easily.\n\nHowever, I'd be willing to trade them for Stonehide Leather.\n\nIf you come upon any, bring it to me and we can make a trade.", objectives = "Obtain 20 Stonehide Leather.", progress = "Do you have leather to trade?", completion = "Thank you, <class>. I'll make good use of this." }
