WordHunterWoW_QuestEN[43153] = { title = "An Eye for a Scepter", description = "Sounds simple? Make nice with Shadow Council friend must... for now. Help with ritual enough to gain trust, then turn tables!\n\nCouncil made portal device to Tol Barad here. Go, help Shadow Council find Eye of Dalaran, earn spot in big ritual! Then steal Scepter!\n\nCalydus will try to keep eye on friend when possible.", objectives = "Take the portal to Tol Barad and help find the Eye of Dalaran.", completion = "Yes, yes! Found the Eye! Helped Shadow Council! Now you go to ritual. Scepter will be there.\n\nTricky it will be friend, but Calydus have great faith in you!" }
