WordHunterWoW_QuestEN[43162] = { title = "Under the Crooked Tree", description = "My three sisters from that tree hung,\nThe crimes accused there was not one,\nThe youngest sister did escape,\nAs the noose looped around their nape,\nOld Ravencrest is the one to blame,\nThis curse for you to lift our shame.", objectives = "Drink from the hag's cauldron to accept her curse. Then you will be able to defeat her sister's restless spirit.", progress = "Steel your heart and drink deep,\n\nReturn my sister back to sleep.", completion = "My dear sister laid to rest,\nA tortured hero proves their best,\nToday I do lift this curse,\nAnd offer you a token, a small purse,\nMy other sisters are still gone,\nThere comes a day to right their wrong..." }
