WordHunterWoW_QuestEN[43181] = { title = "Tracking Down the Scepter", description = "The logbook contains the latest information on the Scepter of Sargeras. It appears to have been written by an extremely agitated, excited, or psychotic imp and is barely legible. Take this to Calydus for translation.", objectives = "Take the logbook to Calydus in Dreadscar Rift.The logbook contains the latest information on the Scepter of Sargeras. It appears to have been written by an extremely agitated, excited, or psychotic imp and is barely legible. Take this to Calydus for translation.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43182] = { title = "The Missing Vessel", description = "So long as Hakkar roams free, no mage will be safe.\n\nMillificent Manastorm created a vessel that siphons the essence of a mage, binding their magic to the object. It was created to be a weapon, but we can use it as bait.\n\nIf I channel my essence into the vessel, it will become an object of pure magic.\n\nUpon capture, Millificent shattered the vessel, allowing it to fall into the hands of our enemies.\n\nFind the pieces and return them to me. Together we can set a trap Hakkar won't be able to resist!", objectives = "Interact with the Scouting Map and complete \"The Missing Vessel\" missions to collect Shattered Vessel Fragments.", progress = "Have you found the missing pieces yet?", completion = "I am relieved that this weapon of destruction is no longer in the hands of our enemies." }
WordHunterWoW_QuestEN[43183] = { title = "Warden Tower Assault: Starstalker's Point", description = "", objectives = "" }
WordHunterWoW_QuestEN[43184] = { title = "Champion: Allari the Souleater", description = "", objectives = "Very astute of you to have saved the best for last.\n\n<Allari smirks playfully.>\n\nIn all seriousness, I am deeply honored that you have chosen me, <name>. Something tells me that the worst is yet to come. We must remain vigilant and bring the Burning Legion to an end." }
WordHunterWoW_QuestEN[43185] = { title = "Champion: Jace Darkweaver", description = "", objectives = "Me? You want me to be one of your champions?\n\nYes, of course. A million times, yes! Just tell me where you want me to go, what you want me to do, and consider it done." }
WordHunterWoW_QuestEN[43186] = { title = "I Am the Slayer!", description = "{name}, we have all gathered here to honor you for your leadership, successes, and sacrifices.", objectives = "Listen as you are honored by the Illidari and the Servants of Illidan.", progress = "The Illidari and the Servants of Illidan are at your disposal.", completion = "Your leadership has provided us with victory after victory. We gladly serve and will sacrifice everything in your name.\n\nAll hail, Slayer <name>!" }
