WordHunterWoW_QuestEN[43249] = { title = "The Raven's Eye", description = "It is imperative that we decipher the SI:7 letter. We must uncover the secrets that it holds before it is too late. But, our best code breakers have yet to make a dent in the cypher.\n\nHowever, we now know that the myth is in fact reality. The Raven's Eye truly exists.\n\nShall we tell the others?", objectives = "Listen to Valeera's tale of the Raven's Eye.", progress = "Are you interested, or not?", completion = "Now, what do you say you and I go to Val'sharah and recover the most powerful jewel in existence?" }
WordHunterWoW_QuestEN[43250] = { title = "Off to Court", description = "The Ravencourt of Black Rook Hold is where we begin our search. It is the ancestral home of Lord Kur'talos Ravencrest, night elven hero of the War of the Ancients. Some of my own ancient ancestors are interred in its cemetery.\n\nMeet me there and make sure that you are not followed. SI:7 is very good at what they do. We have to be better.", objectives = "Meet up with Valeera Sanguinar at Ravencourt in Val'sharah.", completion = "Now that you are finally here, we can begin.\n\nThe elves here have somehow risen from the dead. They are deluded. They think that we are the Burning Legion and have come here to destroy Black Rook Hold." }
WordHunterWoW_QuestEN[43251] = { title = "In Search of the Eye", description = "The Raven's Eye should be somewhere within the courtyard. This is where Ravencrest's lieutenants used to plan their strategies in life. Hell, it looks like they still might be doing so in death.\n\nIt has to be around here somewhere. Your skill at lock picking should prove invaluable.", objectives = "Pick the locks of the Ancient Chests to find the Raven's Eye.", progress = "Have you found the Raven's Eye yet?", completion = "A ledger? Wait, let me look.\n\n<Valeera reaches out and begins thumbing through the tome's pages.>\n\nThis is the key!" }
WordHunterWoW_QuestEN[43252] = { title = "Eternal Unrest", description = "My ancient ancestors are buried here in the cemetery to the west. Because of whatever is causing the dead to rise, their souls are now at unrest.\n\nAll blood elves are descended from high elves, who in turn came from these lands before they were sundered.\n\nI cannot bring myself to do it. Will you put my ancestors to rest?", objectives = "Put Cesta Stargazer, Mandrel Nightsbane, and T'rel Moonblade to rest.", completion = "Thank you, <name>. It means a great deal to me that you have given my ancient ancestors the peace they deserve." }
WordHunterWoW_QuestEN[43253] = { title = "Maw of Souls: Ancient Vrykul Legends", description = "Our diversionary tactics in Stormheim uncovered intel on something I thought only a myth.\n\nThere is a legend about a magical jewel the vrykul created long before the time of man. The jewel was said to be able to...\n\n<Valeera stops herself from continuing while looking around and eyeing you wryly.>\n\nI do not want to talk about it just yet. Not until we have proof.\n\nUnfortunately, the only way we are going to get that proof is in the Maw of Souls on the Naglfar... the ship of the dead.", objectives = "Gather a group and take an etching of the Raven's Eye Tablet on the ship of the dead, The Naglfar, in the Maw of Souls.", progress = "Did you find proof?", completion = "The legend was true! I was right about my suspicions. I had heard about Ravencrest's almost perfect espionage team during the War of the Ancients. Now we know how they got their information.\n\nThe others will not believe it when we tell them. Of course, we could keep it to ourselves.\n\n<Valeera considers for a weighty moment.>\n\nNo. That is how the foolish and greedy lose their heads. We will spread the risk around to everyone." }
WordHunterWoW_QuestEN[43254] = { title = "Ritual Ruination", description = "Time for main event, friend! Gul'dan wants to begin his big ritual, cause end times for this world. Calydus confident getting the Scepter will stop that plan.\n\nTake this bat to Tomb of Sargeras, find ritual, steal Scepter. Oh... and get out!\n\nCalydus will help when he can! Good luck, friend!", objectives = "Take the Fel Bat to the Tomb of Sargeras and steal the Scepter of Sargeras.", completion = "Calydus not believe that worked! Ritual messed up, Shadow Council wiped out, and we not dead!\n\nOh, and you have Scepter! Big win for friend!" }
WordHunterWoW_QuestEN[43255] = { title = "Treasure 061 - Nastrondir", description = "", objectives = "" }
WordHunterWoW_QuestEN[43259] = { title = "Beware of the Crooked Tree", description = "{race}, you must be warned. There is great evil in Val'sharah. I've seen it, and I wish I hadn't. If you take my advice, you will stay far away from the crooked tree in Bradensbrook.", objectives = "Investigate the crooked tree in Bradensbrook.", completion = "So you've come to the crooked tree,\n\nTo name a foe you ask of me,\n\nBut listen first to my tragic tale,\n\nThen you will hear my sister's wail..." }
WordHunterWoW_QuestEN[43260] = { title = "Growing Power", description = "It appears ye and yer weapon are both growin' in strength. Return to me at Netherlight Temple. I have more to show ye.", objectives = "Use the Altar of Light and Shadow to imbue your artifact, then speak to Betild Deepanvil in Netherlight Temple." }
WordHunterWoW_QuestEN[43261] = { title = "Champion: Vanessa VanCleef", description = "", objectives = "After all that, you want me as your champion?\n\n<Vanessa gives you a look of disbelief as she takes a moment before replying.>\n\nFine, but I do things my way. Agreed?" }
WordHunterWoW_QuestEN[43262] = { title = "Champion: Garona Halforcen", description = "", objectives = "<Garona spins one of her razor-sharp blades around her fingers before deftly sheathing it at her waist.>\n\nAs long as there's a challenge to the kill, I'm game for whatever little missions you have in mind." }
WordHunterWoW_QuestEN[43263] = { title = "Growing Power", description = "The bond between you and your weapon has grown stronger, Deathlord. The time has come for you to direct the flow of power within your artifact.\n\nReturn to Acherus and speak with me when you have made your choice.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Soul Forge to imbue your artifact, then speak with Highlord Darion Mograine." }
WordHunterWoW_QuestEN[43264] = { title = "Rise, Champions", description = "Your power is great, Deathlord, but power alone will not be sufficient.\n\nIf we are to save this world from the onslaught of the Burning Legion, then you will need powerful allies. The Knights of the Ebon Blade are yours to command, it will be wise to make use of them effectively.\n\nGo and speak with Nazgrim and Thassarian. They will be of great use to you in the fight against the Burning Legion.", objectives = "Recruit Nazgrim and Thassarian.", completion = "Well done, Deathlord. Nazgrim and Thassarian are powerful champions. I am sure they will carry out their orders with deadly precision." }
WordHunterWoW_QuestEN[43265] = { title = "Spread the Word", description = "Now that you have recruited your champions, you can use the Scouting Map to complete vital missions across the Broken Isles.\n\nThe first mission is critical to the growth and power of our order. Send Nazgrim and Thassarian to seek out new candidates for the Ebon Blade.\n\nOur order must grow in strength if we are to defeat the Burning Legion.", objectives = "Use the Scouting map and complete \"Spread the Word.\"", progress = "What is the status of the mission?", completion = "It appears that Nazgrim and Thassarian were successful in their mission. We have identified several promising candidates to aid us in the war against the Burning Legion." }
WordHunterWoW_QuestEN[43266] = { title = "Recruiting the Troops", description = "A powerful necromancer has joined the cause of the Ebon Blade.\n\nDark Summoner Marogh has come a long way to us from deep within the realm of the Shadowlands. He will be a powerful ally of the Ebon Blade.\n\nSpeak with Dark Summoner Marogh to begin raising an army of ghouls for the Ebon Blade.", objectives = "Speak with Dark Summoner Marogh to summon ghouls.", progress = "Has Dark Summoner Marogh begun his work?", completion = "Good work, Deathlord.\n\nThese ghouls will be invaluable in the war effort on the Broken Isles. Deploy them on missions just as you would your other champions." }
WordHunterWoW_QuestEN[43267] = { title = "Troops in the Field", description = "It's time to send our newly summoned ghouls out into the field. Look at the Command Table and send your champions and troops on a routine scouting mission.", objectives = "Use the Command Table and complete the mission, \"Troops in the Field.\"", progress = "How did it go?", completion = "Excellent work, Deathlord. The mission was a complete success.\n\nWith continued success in the field, the Burning Legion will surely be beaten back." }
WordHunterWoW_QuestEN[43268] = { title = "Tech It Up A Notch", description = "Archivist Zubashi has been doing a great deal of research on the necropolis we call Acherus.\n\nThrough his studies on the necropolis, he has located a number of potential improvements that can greatly increase the power of the Ebon Hold.\n\nSpeak with Archivist Zubashi now and he will show you what improvements can be made.", objectives = "Speak with Archivist Zubashi in Acherus.", progress = "Greetings, Deathlord. I have been studyin' da true nature of da necropolis. You going to be pleased wit' da results I assure you!", completion = "That was an excellent choice, Deathlord. Feel free to speak to Zubashi whenever you require further upgrades." }
WordHunterWoW_QuestEN[43270] = { title = "Rise, Champions", description = "As leader of our order, other priests will look to you for guidance. Many will be willing to pledge themselves to you, doing whatever is necessary to bring down the Burning Legion.\n\nAfter your display of power during the cleansing ritual, there will be many who are eager to serve at your side. Seek out those priests, and let them ease the burden of leadership.", objectives = "Recruit Calia Menethil and High Priestess Ishanah.", completion = "Excellent. Calia Menethil and High Priestess Ishanah are worthy champions. We can trust them to carry out any task we ask of them." }
WordHunterWoW_QuestEN[43271] = { title = "Champion: Calia Menethil", description = "", objectives = "Well met, <name>. It's an honor to serve at your side.\n\nI'm happy to help in any way I can." }
WordHunterWoW_QuestEN[43272] = { title = "Champion: High Priestess Ishanah", description = "[PH]", objectives = "[ph] Recruit your champions.", completion = "Your efforts to restore Saa'ra have not gone unnoticed. As a humble servant of the Sha'tar, I thank you.\n\nAs leader of the Aldor, it is my duty to safeguard all that is holy. This temple is a beacon of light that must be protected.\n\nYou can count me among your allies, willing to do whatever is necessary to destroy the Burning Legion." }
WordHunterWoW_QuestEN[43273] = { title = "Spread the Word", description = "In the center of the dais is a map of the Broken Isles. From it, you can direct our allies to carry out vital assignments across the world.\n\nThe first task is critical to the growth of our order - identifying skilled priests whom we can trust to train our order's troops.\n\nThis is a task we can easily entrust to one of our new champions.", objectives = "Use the Command Map and complete the mission, \"Spread the Word\".", progress = "How is the mission proceeding?", completion = "Calia's mission was a success! We may be seeing some new faces around here soon." }
WordHunterWoW_QuestEN[43274] = { title = "reuse me", description = "[PH]You will receive:", objectives = "[ph] Recruit your champions.[PH]You will receive:" }
WordHunterWoW_QuestEN[43275] = { title = "Recruiting the Troops", description = "Our recruiting efforts have paid off. Grand Anchorite Gesslar has pledged his service to our order.\n\nHe has an eye for greatness, and can easily spot a recruit with potential. He takes those selected under his wing, and shapes them into worthy allies.\n\nSpeak to him now and train a troop of acolytes.", objectives = "Speak to Grand Anchorite Gesslar and train a troop of acolytes.", progress = "How did the training go?", completion = "Excellent. These troops will be invaluable in our defense of the Broken Isles. Deploy them on missions, just as you would with our champions." }
WordHunterWoW_QuestEN[43276] = { title = "Troops in the Field", description = "It's time to send our newly trained acolytes out into the field. Look at the Command Map and send your champions and troops on a routine scouting mission.", objectives = "Use the Command Map and complete the mission, \"Troops in Training\".", progress = "How did it go?", completion = "The scouting mission was more successful than we could have imagined, <name>.\n\nYour troops were able to rescue Archon Torias, a skilled researcher whose knowledge extends far beyond light and shadow.\n\nIn thanks, he has agreed to lend his expertise to our cause." }
WordHunterWoW_QuestEN[43277] = { title = "Tech It Up A Notch", description = "We are very fortunate to have come across Archon Torias.\n\nHis knowledge will be invaluable as we improve our defenders and fortify Netherlight Temple.", objectives = "Speak to Archon Torias in Netherlight Temple.", progress = "Have you had a chance to speak with Archon Torias yet?", completion = "Excellent choice, <name>. Archon Torias will continue to conduct his research in Netherlight Temple. Speak to him when you want to make additional upgrades." }
