WordHunterWoW_QuestEN[43309] = { title = "The Perfect Opportunity", description = "I have heard whispers from Suramar City.\n\nRecent unrest in the city has prompted the nobles to seek another advisor to fill Elisande's council. Such positions are rarely offered and hotly contested.\n\nThis is the perfect opportunity and Ly'leth is the perfect candidate. Fate smiles upon our cause!\n\nI know she has historically chosen to avoid such politics and maneuvering, but we must now ask her to join the fray.\n\nSeek her out at the Waning Crescent and ensure her victory.", objectives = "Meet Ly'leth Lunastre at the Waning Crescent.", progress = "Thalyssra asks much of me.", completion = "Ahh, <name>.\n\nSo good to see you once again. I trust you are ready to assist me with my campaign." }
WordHunterWoW_QuestEN[43310] = { title = "Either With Us", description = "Thalyssra asks much of me, but our cause is worth the risks.\n\nThe title of advisor would grant us enormous influence. Information. Access.\n\nI could change this rebellion. I could save so many lives.\n\nI will need strong endorsement to ascend, though. There are many houses who stand with me by virtue of my family's name. Some are more hesitant.\n\nLady Aurore of House Astravar is the most prominent of these. Seek her out. Offer your aid in my stead. \n\nEarn her trust and the rest will follow.", objectives = "Speak to Lady Aurore.", completion = "I love Lady Lunastre like a sister, but I am afraid my hands are tied." }
WordHunterWoW_QuestEN[43311] = { title = "Or Against Us", description = "If Ly'leth is to achieve the role of advisor to the Grand Magistrix we will need to open a path for her.\n\nIt is true she will have some supporters but they alone cannot grant her the title.\n\nThere are other houses that Ly'leth must contend with. Fear and coercion are their tools. None dare stand against them openly, and we cannot win them over with favors and oaths. \n\nSeek out Arluin. I trust he will have some ideas of how to proceed.", objectives = "Speak to Arluin.", progress = "Yes, I know why you are here. Yes, I can get the jobe done. No, it will not be free.", completion = "Very well. Let us talk strategy." }
WordHunterWoW_QuestEN[43312] = { title = "Thinly Veiled Threats", description = "How could I let this happen?\n\n<Aurore wrings her hands.>\n\nYesterday Coryn Stelleris approached me about the appointment. He sought my support, but I did not offer it. \n\nHe said my son's life would continue as normal... if I gave him my vote.\n\nThis morning my son was gone.\n\nI can only think of the terrible things he may be suffering. You know what this family is capable of!\n\nYou want my support, but I can do nothing while my son is in danger. Nothing.\n\nPlease... save him!", objectives = "Rescue Ailen Astravar.", progress = "Did you find my son?", completion = "He is unharmed! I owe you- and Ly'leth- a great debt." }
WordHunterWoW_QuestEN[43313] = { title = "Rumor Has It", description = "Coryn Stelleris and Ruven Duskmere were close friends, but one always overshadowed the other. Now the Stelleris family stands to gain from lord Ruven's death. Handsomely.\n\nHouse Duskmere will soon learn of their loss. I want you to be the one to redirect their anger and grief.\n\nA handful of well placed rumors should do the trick.\n\nI won't be lingering in this part of the city for long, and Ly'leth will want to know of your efforts.\n\nReturn to her when you are finished.", objectives = "Plant rumors among members of House Duskmere.", completion = "The city is buzzing with very interesting gossip, <name>. Victory is that much closer." }
WordHunterWoW_QuestEN[43314] = { title = "Court of Stars: Beware the Fury of a Patient Elf", description = "An opportunity presents itself, {name}.\n\nLy'leth has arranged to grant you entry into a ball at the Court of Stars. I do not know what we may gain from this venture, but there is one task I must set for you.\n\nAdvisor Melandrus once called himself my ally. He and I planned Elisande's downfall, but when the moment came I found myself betrayed.\n\nThe wound his dagger inflicted still aches. I cannot enter Suramar to take my revenge, but you can.\n\nGive him a traitor's death, and bring me his spellstone.", objectives = "Enter the Court of Stars dungeon and slay Advisor Melandrus. Collect his Spellstone and return it to Thalyssra.", progress = "Is it done?", completion = "<Thalyssra clutches the spellstone tightly for a moment.>\n\nHe brought this upon himself.\n\nI cannot linger in the past. Elisande is weaker without him, and we are one step closer to righting the wrongs inflicted upon the shal'dorei." }
WordHunterWoW_QuestEN[43315] = { title = "Death Becomes Him", description = "There are two houses that pose a threat to Ly'leth's rise, but we concern ourselves with only one of them now.\n\nHouse Duskmere commands respect through fear and that fear is not unfounded. Few can boast of magical talent equal to that of Ruven Duskmere. \n\nWithout this charming specimen, however, their house is nothing.\n\nI know you may find my methods distasteful. Know that there were demons in Suramar long before the Legion.\n\nThis one has lived long enough.", objectives = "Slay Ruven Duskmere.", progress = "Is it done?", completion = "It seemed as though you had that well in hand. I did not want to... interrupt.\n\nThat is one less power hoarding noble to worry about. Well done, <name>." }
WordHunterWoW_QuestEN[43316] = { title = "By Invitation Only", description = "While you were keeping His Highness busy, I found something of interest to Ly'leth and the others.\n\n<Arluin dangles a colorful, elaborately decorated scroll in front of you.>\n\nIt is an invitation. To a party. A party which all of the Suramar nobility will be attending.\n\nNot least on the guest list is Grand Magistrix Elisande herself.\n\nIf you are thinking what I am thinking, then you would agree that Ly'leth needs to know about this.\n\nImmediately.", objectives = "Bring Ly'leth Lunastre the Hand-Scribed Invitation.While you were keeping His Highness busy, I found something of interest to Ly'leth and the others.\n\n<Arluin dangles a colorful, elaborately decorated scroll in front of you.>\n\nIt is an invitation. To a party. A party which all of the Suramar nobility will be attending.\n\nNot least on the guest list is Grand Magistrix Elisande herself.\n\nIf you are thinking what I am thinking, then you would agree that Ly'leth needs to know about this.\n\nImmediately." }
WordHunterWoW_QuestEN[43317] = { title = "In the Bag", description = "Already the city is abuzz with outrage.\n\nI will not lie to you- it pleases me greatly that one such as Coryn is made a fool.\n\nThe other houses have sent their endorsements. It is done, and nothing remains but a formal ceremony to grant me the title of advisor.\n\nMeet me there. You deserve to share in this success.", objectives = "Witness Ly'leth Lunastre's ascension to advisor.", progress = "I am prepared. It is nearly time.", completion = "This may not end as cleanly as I would have preferred." }
WordHunterWoW_QuestEN[43318] = { title = "Ly'leth's Champion", description = "Tal'ashar is an honor duel.\n\nIf I lose, then I must forfeit my title to Coryn Stelleris.\n\n<Ly'leth smiles gently.>\n\nThat is why you are going to fight for me. \n\nI will grant you a more powerful disguise for this task, and together we will put Coryn in his place.\n\nSpeak to me when you are ready to battle on my behalf.", objectives = "Speak with Ly'leth to begin the encounter.", progress = "I know you will defend my honor, <name>.", completion = "We made great strides today. I will not forget this." }
WordHunterWoW_QuestEN[43319] = { title = "The Way of the Tiger", description = "Among the allies who joined us from Tian Monastery is Gin Lai, a monk famed for his experience in the ways of the tiger.\n\nWith his help, we will be able to train Tiger Initiates, who strike swiftly and precisely on the field of battle.\n\nGo speak with him now and request his services.", objectives = "Speak to Recruiter Gin Lai.", completion = "I will do my best to teach the way of the tiger, Grandmaster: to observe the enemy, and strike without hesitation. Soon, our initiates will be ready for battle." }
WordHunterWoW_QuestEN[43323] = { title = "A Time to Reflect", description = "It is time to reflect on the events that have brought us to this moment. A celebration of our great history and the events that shape it.", objectives = "Correctly answer one of Llore's questions about the history of Azeroth.", progress = "Let us speak, then, of events that have already come to pass.", completion = "A moment to reminisce on how far we have come. A day to look to the future and where we might go. A year of reflection on what it means to grow and a lifetime of memories made by those brave enough to seize it." }
WordHunterWoW_QuestEN[43324] = { title = "Rage of the Owlbeasts", description = "", objectives = "" }
WordHunterWoW_QuestEN[43325] = { title = "Ley Race", description = "", objectives = "" }
WordHunterWoW_QuestEN[43326] = { title = "Scouting", description = "", objectives = "" }
WordHunterWoW_QuestEN[43327] = { title = "The Magic of Flight", description = "", objectives = "" }
WordHunterWoW_QuestEN[43328] = { title = "Enigmatic", description = "", objectives = "" }
WordHunterWoW_QuestEN[43330] = { title = "Fire for Effect", description = "", objectives = "" }
WordHunterWoW_QuestEN[43331] = { title = "Time to Collect", description = "Hey there, pal. My sources around here say you had a run-in with the Sixtrigger brothers. I'd imagine you're not very happy with them?\n\nLet's just say we're not exactly friends either.\n\nSo I'll tell you what. How about I let you in on some intel about their current location? Maybe they might have an unfortunate accident, you follow?\n\nOh, and bring some friends. They're not exactly the easiest of targets.", objectives = "Collect Sixtrigger's Key from Rax Sixtrigger in Stormheim.", progress = "This seems to be where the Sixtrigger brothers keep their most prized spoils.", completion = "With the Sixtrigger brothers ended, you're finally able to collect your payment for services rendered.\n\nYou rummage through their most prized possessions and take your pick." }
WordHunterWoW_QuestEN[43332] = { title = "Grell in a Handbasket", description = "", objectives = "" }
WordHunterWoW_QuestEN[43333] = { title = "DANGER: Nylaathria the Forgotten", description = "", objectives = "" }
WordHunterWoW_QuestEN[43334] = { title = "The Coming Storm", description = "You saved us all, my friend! Truly you embody all the elements stand for.\n\nIf the Earthen Ring is to prevail, we will need weapons of great power. I know where to find some. After the Pandaren Campaign, the weapons of the storm god Ra-den were discovered beneath the Throne of Thunder. None have been able to wield them, so great is their power.\n\nThey were placed in the care of the White Tiger, who will give them only to one who is worthy. Come {name}! Travel with me to Pandaria and we will prove your worth!", objectives = "Travel to Pandaria and speak to the White Tiger at his temple.", completion = "Welcome <class>! You seek the weapons of the storm god Ra-den?\n\nMany have traveled here to Pandaria, but none have proven themselves worthy." }
WordHunterWoW_QuestEN[43335] = { title = "Survival Skills", description = "The life of a hunter should never be dull. Living in the wild you never know what will happen next, but you survive on skill and instinct.\n\nShow me you have the basic survival skills to live off the land.", objectives = "Show your survival skill by building a campfire from chopped wood, and cooking a steak over an open flame.", progress = "You need to eat to survive in the wild.\n\nBoar meat makes an excellent meal when cooked over an open flame. It should not be eaten raw, however.\n\nThere are many berries that grow in this region. Some are edible, while others cause minor sickness when ingested. You can often tell which are safe to eat by their smell. A sweet aroma often indicates the berry is unsafe to eat.\n\nThe best firewood can be obtained from dying trees. They are easily identified by their fading, purple leaves.", completion = "You built your campfire with ease, and put a perfect sear on that steak. I'm impressed... and hungry." }
WordHunterWoW_QuestEN[43336] = { title = "Purge of the Nightmare", description = "", objectives = "" }
WordHunterWoW_QuestEN[43337] = { title = "Met Sylvanas With Windrunner Bow", description = "", objectives = "" }
WordHunterWoW_QuestEN[43338] = { title = "The Codex of Ra", description = "The Thunder King conquered Pandaria using power stolen from the Titan Keeper Ra, known as \"Ra-den\" in the mogu tongue. If you truly seek to wield the relics of the Highkeeper, seek out his ancient edicts among the ruins in the heart of the mogu empire: The Edict of Stone, The Edict of Fire, and the Edict of the Storm.\n\nThese pieces of the codex are scattered amongst the Guo-Lai Halls in the Vale of Eternal Blossoms, one in each wing.", objectives = "Enter the Guo Lai Halls in the Vale of Eternal Blossoms and collect the Edict of Stone, the Edict of Fire, and the Edict of the Storm. Cleanse the area by slaying mogu spirits.", progress = "I've been asking around. The pandaren locals are terrified of this place. It's been haunted since the end of Hellscream's Pandaren Campaign.\n\nDid you find an offering for the White Tiger?", completion = "That tiger is serious about this, isn't he?\n\nWhile you were here, others came to the Temple of the White Tiger to present their offerings to him. It looks like we're going to have some competition." }
WordHunterWoW_QuestEN[43340] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[43341] = { title = "Uniting the Isles", description = "There are a great number of factions here on the Broken Isles. We must unite them if we want to stand a chance against the Legion. Prove your worth to them and report back to me.", objectives = "Earn at least Friendly reputation with the factions of the Broken Isles.", progress = "Any luck uniting the factions?", completion = "Excellent work, <name>. We still have a long road ahead of us to rid this world of the Legion, but this brings us one step closer." }
WordHunterWoW_QuestEN[43342] = { title = "Vignette - Roteye", description = "", objectives = "" }
WordHunterWoW_QuestEN[43343] = { title = "Vignette: Dread-Rider Cortis", description = "", objectives = "" }
WordHunterWoW_QuestEN[43344] = { title = "DANGER: Aodh Witherpetal", description = "", objectives = "" }
WordHunterWoW_QuestEN[43345] = { title = "DANGER: Harbinger of Screams", description = "", objectives = "" }
WordHunterWoW_QuestEN[43346] = { title = "DANGER: Ealdis", description = "", objectives = "" }
WordHunterWoW_QuestEN[43347] = { title = "DANGER: Rabxach", description = "", objectives = "" }
WordHunterWoW_QuestEN[43348] = { title = "Vignette: Magister Phaedris", description = "", objectives = "" }
WordHunterWoW_QuestEN[43349] = { title = "The Aegis of Aggramar", description = "Now that it's out of the hands of the Legion, the Aegis should be brought back to Dalaran for safekeeping while the hunt continues for the rest of the Pillars of Creation.\n\nIt should be safe in the central portal chamber until the time comes when it is needed.", objectives = "Secure the Aegis of Aggramar in the Chamber of the Guardian in Dalaran.", completion = "The Aegis of Aggramar is secure within the well-defended city of Dalaran.\n\nYour quest to drive back the Legion is one step closer to fruition." }
WordHunterWoW_QuestEN[43351] = { title = "Mal'Dreth the Corrupter", description = "", objectives = "" }
WordHunterWoW_QuestEN[43352] = { title = "Asset Security", description = "With the demons and guards so agitated, I'm running out of safe places to store contraband. The guards have caught on to one of my favorite havens and will be making off with my goods any minute now.\n\nHead to my stash and discourage their curiosity. You will need to use a grappling hook to access it- just look for something to latch onto along the ledge.\n\nI will make sure there is something in it for you when you are done.", objectives = "Defend Arluin's stash from the city guards.", progress = "Did you deter them yet?", completion = "You're becoming quite the dependable associate." }
WordHunterWoW_QuestEN[43353] = { title = "Tracking Quest: Celestine of the Harvest", description = "", objectives = "" }
WordHunterWoW_QuestEN[43354] = { title = "Tracking Quest: Thisalee Crow", description = "", objectives = "" }
WordHunterWoW_QuestEN[43355] = { title = "Tracking Quest: Matoclaw", description = "", objectives = "" }
WordHunterWoW_QuestEN[43356] = { title = "Tracking Quest: Talza", description = "", objectives = "" }
WordHunterWoW_QuestEN[43357] = { title = "Tracking Quest: Graham Silverclaw", description = "", objectives = "" }
WordHunterWoW_QuestEN[43358] = { title = "Vignette: Myonix", description = "", objectives = "" }
WordHunterWoW_QuestEN[43359] = { title = "A Hero's Weapon", description = "Grand Master, you have saved our order from the brink of destruction.\n\nYour deeds have shown us that with effort and determination we can overcome any challenge. In light of your example, we have doubled our efforts and developed a technique that will awaken your weapon to its true potential.\n\nPlease, stand before the Forge of the Roaring Mountain and raise your weapon high.", objectives = "Approach the indicated location before the Forge of the Roaring Mountain and raise your weapon.", progress = "We honor you, Grandmaster.", completion = "May the new powers of your weapon aid you in the times ahead." }
WordHunterWoW_QuestEN[43360] = { title = "The Shardmaidens", description = "Long have I walked this land and I have seen many forms of corruption.\n\nThe creatures that wander this hall are twisted by the magics unleashed by the failed arcan'dor. These dryads have lost their way, and cannot be saved.\n\nYou must destroy them. End their suffering.", objectives = "Slay 6 Shardmaidens in the Shattered Locus.", completion = "Thank you. This place will never recover, but their madness need not harm others." }
WordHunterWoW_QuestEN[43361] = { title = "Fragments of Disaster", description = "In the hall beyond rests the bones of the failed arcan'dor.\n\nI will take fragments of the crystallized tree and attempt to read them. We must discover the root cause of this destruction.\n\nOnly then do we have any hope of preventing this disaster from repeating itself.", objectives = "Collect 5 Crystallized Bark.", progress = "Do you have the shards?", completion = "I will study these carefully. If we are fortunate, there will be answers." }
WordHunterWoW_QuestEN[43362] = { title = "The Stuff of Dreams", description = "This arcan'dor is one of an ancient species. They were not bred, but created. In them the arcane and primitive druidic magics merged into something greater than both.\n\nThe arcane will soon devour it whole.\n\nWe can restore balance, but it will require wild magic. Magic trapped in another realm.\n\nYou must enter the Emerald Dreamway and bring back the essence of life itself.\n\nOnly then can the arcan'dor find stability and begin to thrive once more.", objectives = "Collect Purified Life Essence from the Emerald Dreamway.", progress = "Do you have it?", completion = "I do not know how you obtained this, but I know it was not easy. Much stands against us, but you prevailed. Come. Let us restore the arcan'dor." }
WordHunterWoW_QuestEN[43363] = { title = "A Winter Veil Gift", description = "", objectives = "A small tag on this present reads:\n\nHappy holidays, <name>!" }
WordHunterWoW_QuestEN[43364] = { title = "A Gently Shaken Gift", description = "", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special <race> <class>." }
WordHunterWoW_QuestEN[43365] = { title = "The Cycle Continues", description = "Yay! The grove is regenerating nicely. Our flower friends thank you for helping them.\n\nWe were able to save most of the grove, but sadly, many living souls were lost as well.\n\nBrightwing is so sad!\n\nBut you can help! Take this bag of Dream Seeds. Plant them onto fresh corpses, and in time, new flowers will grow!\n\nDeath is beautiful, and from death comes rebirth. This is the cycle that must continue!", objectives = "Plant 100 Dream Seeds on corpses.", completion = "Thank you... it gives Brightwing much peace to know that life continues." }
WordHunterWoW_QuestEN[43366] = { title = "Talked with Mimiron", description = "", objectives = "" }
WordHunterWoW_QuestEN[43367] = { title = "Pixie Dust", description = "Friend, you have done so much for Brightwing, but there is still so much more to do.\n\nI've been working so hard to restore the grove, but my magic is drained.\n\n<Brightwing's stomach grumbles loudly.>\n\nWithout magic, my work cannot continue. The enchanters of your people use a magical dust that can revitalize me quickly.\n\nIf you bring me some, I can work much faster!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring 50 Arkhana to Brightwing. Arkhana is obtained through the enchanting profession." }
WordHunterWoW_QuestEN[43368] = { title = "Champion: Brightwing", description = "", objectives = "Your heroic efforts within the Emerald Dream were inspiring, <name>. The Dream is safe for now, but it remains threatened as long as Xavius lives.\n\nI will lend you my aid. Together, let us keep Azeroth safe from those who would seek its destruction." }
WordHunterWoW_QuestEN[43369] = { title = "Vignette: Siegemaster Aedrin", description = "", objectives = "" }
WordHunterWoW_QuestEN[43370] = { title = "A New Invention", description = "I have been experimenting with technology that allows you to alter the structure of beasts, specifically with how they look.", objectives = "I should be able to create an item that allows you to change the appearance of Hati, but the components for such an item are rare. The Squallhunters from Stormheim have a Stormy Gland, and the Stoneblood Harpies near Thas'talah in Val'sharah have Pristine Harpy Feathers that I need. The Hatecoil Naga near the Ruins of Nar'thalas in Azsuna are said to have Reflective Scales, and finally I need an Essence of Pure Spirit from the Seabound Mystics in the Blind Marshlands of Highmountain.", progress = "This is my most magnificent invention I have made. In the last 10 minutes.", completion = "Here you go, <name>. Take care of Hati and the Titanstrike and be safe in your adventures." }
WordHunterWoW_QuestEN[43371] = { title = "Relieving the Front Lines", description = "Many within our order have been on the front lines of battle for too long, aiding those who are attempting to thwart the Legion's invasion.\n\nIt is time we send in some relief, allowing our allies some much needed rest.", objectives = "Interact with the Command Map and complete the mission, \"Relieving the Front Lines\".", completion = "Hopefully our priests have a chance to rest before heading back into battle." }
WordHunterWoW_QuestEN[43372] = { title = "Whispers in the Void", description = "Our priests are resting and recuperating, but one not as well as the others. Gilner Greymoss lingers within the Sanctuary of the Void, laughing to himself.\n\nHe refuses to leave, but his presence is making the other priests uneasy.\n\nPerhaps you should speak to him and see what is wrong?", objectives = "Speak to Gilner Greymoss in the Sanctuary of the Void.", progress = "Some wounds are too deep to heal.", completion = "Gilner's hearing voices, is he? All that dabbling in the shadows has finally caught up to him." }
WordHunterWoW_QuestEN[43373] = { title = "The Best and Brightest", description = "If we wish to see the truth in Gilner's ramblings, I will need to induce a vision.\n\nIt is not the sort of thing that is typically forced, but we have within our ranks the best and brightest alchemists who can craft an extract that will grant me the sight I need.\n\nSeek them out in Azsuna where they are currently aiding those on the front lines.", objectives = "Find Zabra Hexx in Azsuna.", completion = "It's a good thing ya showed up when you did.\n\nSo Velen wants to induce a vision? That's no easy task, but it's nothing Yalia and I can't handle." }
WordHunterWoW_QuestEN[43374] = { title = "Murloc Mind Control", description = "Yalia and I were deliverin' antidotes to da front lines a Faronaar when we were attacked by a herd a murlocs. We dropped our supplies and made a run for it, but Yalia never made it out a da camp. Obviously I didn't fair much better, ma bones still ache from bein' turned to stone.\n\nIt's possible Yalia's still alive and bein' held captive. Please, ya have to find her!", objectives = "Rescue Yalia Sagewhisper from the murlocs within El'dranil Shallows.", completion = "Your quick thinking got me out of a terrible situation. Thank you, <name>." }
WordHunterWoW_QuestEN[43375] = { title = "An Ample Supply", description = "Durin' our attempt to flee da murlocs, Yalia and I dropped da supplies we planned to deliver to da demon hunters in Faronaar.\n\nInside each a those crates were vials a salve dat took us countless days and resources to craft. If we don' get those supplies back, I fear our allies on da front lines will suffer.", objectives = "Recover Felbat Toxin Salve from supply crates scattered around El'dranil Shallows.", progress = "Do ya have our supplies?", completion = "There's no tellin' how many lives ya saved by recoverin' these vials." }
WordHunterWoW_QuestEN[43376] = { title = "Problem Salver", description = "Forcing a vision isn't easy by any means. Finding the ingredients for the elixir alone will take a considerable amount of time, time we don't have. Too many are suffering on the front lines as we speak, in need of the salve we were meant to deliver.\n\nI suppose if we all work together, we can make this work.\n\nZabra and I will find the items needed for Velen's elixir, if you take the salve to Faronaar and cure the demon hunters. Does that sound fair?", objectives = "Use the salve on diseased demon hunters at Faronaar Front in Azsuna.", completion = "We've found the ingredients we'll need for Velen's elixir." }
WordHunterWoW_QuestEN[43377] = { title = "Halls of Valor: The Light Within", description = "We cannot ignore the Prophet's vision, {name}. To do so would mean that everything we know and hold dear will be lost to the Legion.\n\nWe must focus on what we know, and that is that the Light must walk among us.\n\nWithin the Halls of Valor you will find an ascending val'kyr by the name of Hyrja. Recover a spark of her Light and release it within our temple.", objectives = "Recover a Spark of Light from Hyrja within the Halls of Valor dungeon.", completion = "<Saa'ra's soothing voice fills your mind.>\n\nYour gift of Light is a welcome one, <class>." }
WordHunterWoW_QuestEN[43378] = { title = "Eye of Azshara: Looking Through the Lens", description = "We have what we need to create Velen's elixir, but in order for others to be able to witness his vision, we'll need to find something that can be used to project images from the mind.\n\nA lens from the nearby naga should work well, but I don't think they're going to be too eager to give it up.", objectives = "Recover the Lens of the Tide from Lady Hatecoil within the Eye of Azshara dungeon.", progress = "Gazing through the lens of a powerful naga will allow you to witness my vision.", completion = "You've returned, and just in time it would seem.\n\nYalia and Zabra have just finished crafting the elixir. This lens will allow you to see what I see when the vision begins." }
WordHunterWoW_QuestEN[43379] = { title = "Velen's Vision", description = "I have everything I need to bring forth a vision, but the question remains: are you ready to witness it? Even the smallest glimpse into the future can weigh heavy on your soul.\n\nOnce I ingest the elixir, the vision will come quickly. Gazing into the Lens of the Tides will allow you to see what I see.\n\nLet me know when you are ready to begin.", objectives = "Use the Lens of the Tides to witness Prophet Velen's vision.", progress = "Even the smallest glimpse into the future can leave a heavy weight on your mind.", completion = "We will not let this demon determine our fate. You have the power to change our future.\n\nI have seen the path to salvation, and you will lead us there.\n\nI must retire for now. The weight of this vision has taken its toll on my mind and body." }
WordHunterWoW_QuestEN[43380] = { title = "Champion: Sol", description = "", objectives = "Born of Light, I fight for Light." }
WordHunterWoW_QuestEN[43381] = { title = "Champion: Mariella Ward", description = "", objectives = "I owe you my life, and so much more.\n\nYou saw something in me worth saving, and allowed me to eventually believe that as well.\n\nLet me live my life with purpose, <name>. Let me fight by your side." }
WordHunterWoW_QuestEN[43382] = { title = "Champion: Natalie Seline", description = "", objectives = "You pulled my spirit from the Void, which is no easy feat. I cannot deny the part of me that would stay there forever, embraced by the shadows.\n\nThe Void is filled with many whispers, <name>. The kind that should have us all worried.\n\nWe cannot afford to be separated by our beliefs. We must come together as priests of both Light and Shadow to face the Burning Legion together." }
WordHunterWoW_QuestEN[43383] = { title = "Awakening the Light", description = "This spark will only know its full potential once it's been filled with pure Light, gleaned from the holiest places in our world.\n\nNurture this spark, and it may grow to walk among you.", objectives = "Collect Pure Holy Light by completing Class Hall missions.", progress = "<Saa'ra's soothing voice fills your mind.>\n\nNurture the spark with holy Light if you wish it to awaken and walk among you.", completion = "<The room begins to warm as the Light expands.>" }
WordHunterWoW_QuestEN[43384] = { title = "Demonic Runes", description = "I cannot stand by idly and allow the Legion to destroy our home. \n\nI've been studying their language for some time, deciphering any runes I can get my hands on, but my supply is severely limited. \n\nIf I had more runes to study, it's possible that I may discover something that will help us in locating Balnazzar.", objectives = "Collect Demonic Runestones from demons throughout the Broken Isles.", progress = "Were you able to recover the runestones?", completion = "These are in excellent condition! Thank you, <name>." }
WordHunterWoW_QuestEN[43385] = { title = "Infiltrating Our Enemies", description = "With the Light at our side, we should focus our efforts on figuring out who among our enemies could be a potential ally.\n\nAny of your champions should be capable of infiltrating enemy ranks, giving us a better understanding of how to approach this.\n\nEven so, it is a delicate task. Proceed with caution.", objectives = "Interact with the Command Map and complete the mission, \"Infiltrating Our Enemies\".", completion = "Your efforts have provided us with the information we need to move forward.\n\nIt's been discovered that there are a few defectors among the Scarlet Onslaught." }
WordHunterWoW_QuestEN[43386] = { title = "Onslaught Envoy", description = "A few defectors have been discovered among the Scarlet Onslaught in Northrend.\n\nI know it's difficult to think that any within their ranks could be useful to our cause, but we must make an attempt.\n\nThe prophecy says an old enemy will become an ally, so it's worth it to investigate and see if these defectors can be brought to the Light.", objectives = "Find a new ally among old enemies in New Hearthglen.", completion = "Why are you here? Why bother saving me? I was prepared to die. I should pay for the terrible things I've done..." }
WordHunterWoW_QuestEN[43387] = { title = "Scarlet Redemption", description = "The Light shines upon me, {name}! For the first time in my life, I feel it!\n\nI was without hope, ready to die for the things I had done in the name of the Scarlet Crusade, but then you appeared! You are my chance at redemption. \n\nPlease, let me prove to you that I am worthy of a second chance. Let me slay those I used to be loyal to!", objectives = "Help Mariella the Heretic redeem herself by killing members of the Scarlet Onslaught in New Hearthglen.", progress = "I will prove myself worthy of being redeemed.", completion = "The Light truly shines upon me, <name>. Your presence has proven that." }
WordHunterWoW_QuestEN[43388] = { title = "Apostate Liberation", description = "There are others like me, you know. Others that have removed the veil that the Scarlet Crusade has kept over our eyes for so long. \n\nThey've been placed in cages, treated like animals, simply because their beliefs no longer line up with what the Onslaught deems is right and holy. \n\nThey wish to redeem themselves. We should try to free them, if you think their lives are worth saving.", objectives = "Rescue Onslaught Apostates within New Hearthglen.", progress = "All we want is a chance to redeem ourselves.", completion = "The mercy you have shown brings tears to my eyes." }
WordHunterWoW_QuestEN[43389] = { title = "Unexpected Guests", description = "You helped me escape my fate by freeing me from the gallows, but allowing me to fight the Scarlet Onslaught by your side has truly freed my heart and mind from the guilt I have felt for so long.\n\nI want to be a part of something greater than myself, a noble cause that won't distort the meaning of the Light. \n\nLet me travel to your temple and beg forgiveness of the Prophet. I may not be a welcome guest, but it's a journey I must make to complete my redemption.", objectives = "Return to Alonsus Faol in Netherlight Temple.", completion = "Is this the enemy we should welcome as an ally?" }
WordHunterWoW_QuestEN[43390] = { title = "Forgotten Shadows", description = "The Light walks among us, as does one of our enemies. You have done well to bring the prophecy to life, but it is not yet complete.\n\nThe shadows must rise, and to do so, the Cult of Forgotten Shadows must be restored. \n\nYou will find the few remaining followers at the cemetery in Duskwood. They linger there near the grave of their fallen leader.", objectives = "Head to Duskwood and meet with a member of the Cult of Forgotten Shadows.", completion = "Alonsus sent you, did he? He's never shown much interest in us before.\n\nOf course, we've never been ones to follow the Light, at least not in the way that most would want us to.\n\nWe embrace the Shadows as well, finding our faith in the balance between both extremes." }
WordHunterWoW_QuestEN[43391] = { title = "Secrets of the Void", description = "Our leader was murdered for her beliefs, or so most would believe.\n\nNatalie Seline knew her fate, and took steps to protect herself from an inevitable death. \n\nThe night her attackers came, Natalie sent her spirit to the Void, its location known only to Natalie herself.\n\nShe penned a spell to retrieve it in one of her many journals, but the tome has since fallen into the hands of those who wished her dead in the first place.\n\nWithout her journal, we will never be able to recover her spirit.", objectives = "Recover Natalie's Journal from Twilight Lord Urgrok.", progress = "We watch over Natalie's body, forever hopeful that her spirit will return.", completion = "This is it! This is the journal that contains the spell to locate Natalie's spirit!" }
WordHunterWoW_QuestEN[43392] = { title = "Into the Void", description = "This is without a doubt Natalie's writing. The entry was scrawled in haste, but the message is clear: The spell within this journal will lead us to Natalie's spirit, but it needs to be incanted at a shadow altar within the catacombs.\n\nOdessa and I have a duty to watch over Natalie's body, but with your considerable power, you should be able to perform the spell with ease.", objectives = "Read Natalie's Journal at the catacomb's shadow altar to enter the void and recover her spirit.", completion = "The lure of the Void is strong. There were times I thought I would be lost there forever.\n\nThank you for freeing me, <name>." }
WordHunterWoW_QuestEN[43393] = { title = "Rising Shadows", description = "News of my return will spread fast among those who share my beliefs. Soon Azeroth will see the rise of Shadows, but I imagine this is not news to you.\n\nWhatever your plan may be, I hope it continues to see the Cult of Forgotten Shadows as allies.", objectives = "Return to Alonsus Faol at Netherlight Temple.", completion = "The Forsaken will rejoice at Natalie Seline's return, and we will as well, knowing that the prophecy is being fulfilled." }
WordHunterWoW_QuestEN[43394] = { title = "Crossing Legion Lines", description = "I've received word from the Highlord that a group of paladins and priests were captured after a battle broke out at Felblaze Ingress. Your priestess, Delas Moonfang, was among those captured.\n\nThey've been taken through the demon portal and into the Legion stronghold of Niskara.\n\nWe will need the assistance of the Conclave if we have any hope of recovering them.", objectives = "Use the demon portal at Felblaze Ingress to enter Niskara and find Aponi Brightmane.", progress = "I've never been so happy to see you, <class>.", completion = "Thank the Light, <class>. I didn't want to give up hope." }
WordHunterWoW_QuestEN[43395] = { title = "Allies of the Light", description = "Both Arator and Delas are still somewhere on this forsaken rock, as well as many of our other allies.\n\nWe cannot leave them, {name}.", objectives = "Save Silver Hand Knights or Conclave Priests, and rescue Arator the Redeemer and Delas Moonfang.", completion = "I already heard of your heroism from Delas Moonfang. Thanks to you, many lives were saved." }
WordHunterWoW_QuestEN[43396] = { title = "The Mind of the Enemy", description = "The demon jailors spoke of an upcoming invasion. Their army is gathering for something big, and it worries me greatly.\n\nLet us find whatever information we can about their plans.", objectives = "Find the Legion Intelligence, Star Map, and Image of Velen, then slay Brood Queen Aramis.", completion = "The intelligence you have gathered is further proof that the prophecy cannot be ignored. The Legion's attack is imminent, and we will not survive without the paladins as our allies under the Light." }
WordHunterWoW_QuestEN[43397] = { title = "United As One", description = "You and Delas have had dealings with the paladins before, maybe it's possible they will grant you an audience with their war council. \n\nHead to the Sanctum of Light and ask the paladins to help us defend Netherlight Temple from Balnazzar's attack.", objectives = "Make your way to the Sanctum of Light to speak with Lady Liadrin, and hear the council of war.", progress = "Now is not the time for interruptions, <name>. The council needs to determine its course of action.", completion = "We will help defend Netherlight Temple and lay a trap for Balnazzar." }
WordHunterWoW_QuestEN[43398] = { title = "Champion: Alonsus Faol", description = "", objectives = "I knew from the moment we met in the quiet fields of Tirisfal that you would be the one to unite the priests.\n\nI'd like to take credit for finding our leader, but I really think the truth of it is, you found us.\n\nOur time together has only just begun, <name>." }
WordHunterWoW_QuestEN[43399] = { title = "Fortifying the Temple", description = "We've all worked so hard turning this temple into something all priests can be proud of, it would be a shame to see it fall to the Burning Legion.\n\nWe must strengthen our defenses in preparation for the attack. With the right resources, we can make the temple a nearly impenetrable fortress.", objectives = "Complete 10 World Quests.", progress = "We will need to gather many resources in order to properly fortify the temple.", completion = "This should be enough to make the necessary improvements to our defenses." }
WordHunterWoW_QuestEN[43400] = { title = "Lumenstone", description = "To prepare for the battle, we will need the best armor and weapons we can get.\n\nLumenstone is an enchanted material that can withstand great amounts of fel magic.\n\nIt is found in rare quantities all over the Broken Isles, and many of the native races use it in their own metalcrafting.\n\nWe should send our champions to target enemies around the Broken Isles - there should be plenty of lumenstone to be found in their stockpiles.", objectives = "Collect 50 Lumenstone by sending champions on \"Lumenstone\" missions.", progress = "Have you acquired any lumenstone?", completion = "There's enough lumenstone here to craft armor and weapons for an army. Nice work, <name>." }
WordHunterWoW_QuestEN[43401] = { title = "A Light in the Darkness", description = "The Burning Legion has begun their attack!\n\nI will remain here and prepare the temple's defenses. You must meet our allies in Dalaran and let them know that the battle has begun!\n\nMake haste, {name}. I do not know how long we will be able to keep Balnazzar at bay.", objectives = "United with the paladins, defend Netherlight Temple and slay Lord Balnazzar.", progress = "The paladins have always been our allies and friends. Now, we stand united against a common cause.", completion = "You fought well, High <class>." }
WordHunterWoW_QuestEN[43402] = { title = "High Priest of Netherlight", description = "You have fulfilled the prophecy, but more than that, you have united the priests of Azeroth.\n\nWe should take a moment to recognize all that you have accomplished.", objectives = "Listen as you are honored by the Conclave of priests.", progress = "We rejoice in your triumph!", completion = "You are a leader worthy of our praise, High <class>." }
WordHunterWoW_QuestEN[43403] = { title = "Defending the Isles", description = "As druids, our charge is to defend nature... and in turn, our home, Azeroth.\n\nConflict breaks out all across the Broken Isles. The Burning Legion pushes forward, and numerous allies call out for our aid.\n\nWe must focus our efforts on defense, before we can mount an offense against the Nightmare.\n\nHelp our allies across the Broken Isles, then return to me when the situation is under control.", objectives = "Complete 10 World Quests.", progress = "Conflict rages across the Broken Isles.", completion = "You have represented the Dreamgrove honorably, Archdruid. Your aid has helped many, and your victories will be spoken of for years to come." }
WordHunterWoW_QuestEN[43404] = { title = "A Gathering for the Grand Master", description = "{name}, err... {class}t,\n\nYour presence is requested for a matter of the greatest importance at the Temple of Five Dawns.\n\nMaster Ponshu and the rest of the Broken Temple are waiting for you!", objectives = "Report to Iron-Body Ponshu in the Temple of Five Dawns.<name>, err... <class>t,\n\nYour presence is requested for a matter of the greatest importance at the Temple of Five Dawns.\n\nMaster Ponshu and the rest of the Broken Temple are waiting for you!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43405] = { title = "Da-Nel's Second Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[43406] = { title = "Request for the Deathlord", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43407] = { title = "A Hero's Weapon", description = "I'm pleased to report that the improvements to the Soul Forge are complete!\n\nWhen you are ready, we shall use it to unlock the true potential of your weapon!", objectives = "Approach the indicated location before the Soul Forge and raise your weapon.", progress = "Suffer well, Deathlord.", completion = "May the new powers of your weapon serve you well." }
WordHunterWoW_QuestEN[43408] = { title = "Summons for the Arch Druid", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43409] = { title = "A Hero's Weapon", description = "{class}t, in our short time together you have done much to aid the Circle.\n\nWe are inspired by your determination and have developed a new technique that will bind the power of your weapon with the Emerald Dream itself!\n\nEverything is prepared. When you are ready we shall begin.", objectives = "Approach the indicated location before the Seed of Ages and raise your weapon.", progress = "We honor you, Archdruid.", completion = "With this new power, the Legion will fall!" }
WordHunterWoW_QuestEN[43410] = { title = "The Master is Requested", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43411] = { title = "The Master is Requested", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43412] = { title = "A Hero's Weapon", description = "I'm pleased to report that the improvements to the Forge are complete!\n\nWhen you are ready, we shall use it to unlock the true potential of your weapon!", objectives = "Approach the indicated location before the Cursed Forge of the Nathrezim and raise your weapon.", progress = "We honor you, Slayer.", completion = "May the new powers of your weapons serve you well." }
WordHunterWoW_QuestEN[43413] = { title = "A Twist in the Nether", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43414] = { title = "A Hero's Weapon", description = "{class}t, our research into the Felblood Altar has proven useful. We've developed a ritual that should unleash the full powers of your artifact weapon!\n\nSay the word, and we shall begin the ritual at once!", objectives = "Approach the indicated location before the Felblood Altar and raise your weapon.", progress = "We honor you, Netherlord.", completion = "With this new power, nothing shall stop us!" }
WordHunterWoW_QuestEN[43415] = { title = "A Hero's Weapon", description = "{class}t, in our short time together you have done much for our order.\n\nThrough your words and deeds we've been inspired to redouble our efforts and I'm proud to report that we've discovered a new technique that may be of use to you.\n\nIf you have a moment, {class}t, I would be pleased to show you the fruit of our research.", objectives = "Approach the indicated location before the Forge of the Guardian and raise your weapon.", progress = "We honor you, Archmage.", completion = "May this power aid you in the times ahead." }
WordHunterWoW_QuestEN[43416] = { title = "Treasure", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43417] = { title = "The Spirits Call", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43418] = { title = "A Hero's Weapon", description = "Farseer, since you have joined us you have done much to aid the Earthen Ring.\n\nYour efforts have not gone unnoticed. The spirits have watched all that you have done and are pleased. They also have shown me a technique that will unleash the true power of your weapon!\n\nThe ritual is ready. When you are prepared we can begin.", objectives = "Approach the indicated location before the Ancient Elemental Altar and raise your weapon.", progress = "We honor you, Farseer.", completion = "May this power aid you in the times ahead." }
WordHunterWoW_QuestEN[43419] = { title = "The Light Beckons", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43420] = { title = "A Hero's Weapon", description = "{class}t, in our short time together you have done much to aid the Conclave. Now, with the work upon the Altar of Light and Shadow complete, it is time that we aid you. We have discovered a method to awaken the full power of your weapon!\n\nPlease, step before the altar and raise your weapon high.", objectives = "Approach the indicated location before the Altar of Light and Shadow and raise your weapon.", progress = "All hail the, High <class>!", completion = "May the new powers of your weapon serve you well." }
WordHunterWoW_QuestEN[43421] = { title = "The Raven Calls", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43422] = { title = "A Hero's Weapon", description = "I'm pleased to say that the improvements to the crucible are complete!\n\nWhen you are prepared, we shall use it to unlock the true potential of your weapons!", objectives = "Approach the indicated location before the Crucible of the Uncrowned and raise your weapon.", progress = "Well done, Shadowblade.", completion = "May your new weapons serve you well." }
WordHunterWoW_QuestEN[43423] = { title = "A Hero's Weapon", description = "I'm pleased to say that the improvements to the Altar of the Eternal Hunt are complete!\n\nWhen you are ready, we shall use it to unlock the full potential of your weapon!", objectives = "Approach the indicated location before the Altar of the Eternal Hunt and raise your weapon.", progress = "Well done, Huntmaster.", completion = "May the new powers of your weapon serve you well." }
WordHunterWoW_QuestEN[43424] = { title = "A Hero's Weapon", description = "{class}t, you've brought together the Silver Hand like no {class}t has done before. You've shown us that with determination and faith in the holy light we can overcome any challenge.\n\nFollowing in your example our workmen have toiled hard to improve the Altar of Ancient Kings, allowing it to unlock the true potential of your weapon.\n\nTheir work is now complete! Step forward when you are ready and we shall begin.", objectives = "Approach the indicated location before the Altar of Ancient Kings and raise your weapon.", progress = "Well done, Highlord.", completion = "May this blessed power aid you in the times ahead." }
WordHunterWoW_QuestEN[43425] = { title = "A Hero's Weapon", description = "I've been watching you, {name}.\n\nTime and again you've led the Valarjar to war with your weapon held high! Time and again the halls of Valhalas have thundered with the cheers of your victory!\n\nNow that the enhancements to the forge have been completed, it is time that your weapon's true potential be unleashed! Meet with me at the forge, hero.", objectives = "Meet with Odyn at his forge and raise your weapon at the indicated location.", progress = "I honor you, Battlelord.", completion = "May your new weapon serve you well." }
