WordHunterWoW_QuestEN[43441] = { title = "A Second Weapon", description = "We have strong leads on other ancient weapons that you might choose to pursue, if having one renowned, powerful piece of history in your hands is somehow insufficient.\n\nI'll lay out the options for you. Let me know how you'd like to proceed.", objectives = "Choose a second artifact to pursue.", completion = "It is decided then." }
