WordHunterWoW_QuestEN[43461] = { title = "A Time to Reflect", description = "It is time to reflect on the events that have brought us to this moment. A celebration of our great history and the events that shape it.", objectives = "Correctly answer one of Ju'Pa's questions about the history of Azeroth.", progress = "Let us speak, then, of events that have already come to pass.", completion = "A moment to reminisce on how far we have come. A day to look to the future and where we might go. A year of reflection on what it means to grow and a lifetime of memories made by those brave enough to seize it." }
WordHunterWoW_QuestEN[43462] = { title = "Mother Ozram", description = "The fiendish imps in this region are an incessant pain on our allies defending the camps below.\n\nThey are the spawn of a wicked imp-mother named Mother Ozram, who has been seen on a hill to the south.\n\nDestroy her, and we will end her brood as well.", objectives = "Kill Mother Ozram.", progress = "Do not be deceived by the imp-mothers. They are devious and strong.", completion = "Good riddance." }
WordHunterWoW_QuestEN[43463] = { title = "Ashes of a Fallen Crusader Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[43464] = { title = "Ashes of a Fallen Crusader Tracking Quest 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[43465] = { title = "Ashes of a Fallen Crusader Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[43466] = { title = "Hidden History", description = "Filmaff believes with a little assistance we can give you more.\n\nThere are a few tomes I could point out - not easy to get, mind you - that would... <Cough>... that would push forward our research a bit.\n\nHere, I'll give you a list.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use Old Filmaff's notes to locate and recover the 4 ancient tomes for Edirah's research." }
WordHunterWoW_QuestEN[43467] = { title = "Boarding the Fel Hammer", description = "", objectives = "" }
WordHunterWoW_QuestEN[43468] = { title = "Blood for the Wolfe", description = "We have a request in from Winstone Wolfe. He says that he needs a rather large amount of demon blood. He was not specific what for, and I did not ask.\n\nI am inclined to do this for him with all expediency. The Wolf rarely asks for anything, so when he does, we jump. He gets results, one-hundred percent of the time and then some.\n\nWe should show him the same professional courtesy.", objectives = "Collect 50 Fel Blood.", progress = "The clock is ticking, <name>. Do you have the blood?", completion = "That ought to do it. I will make sure that The Wolf gets every drop.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[43469] = { title = "Where In the World is Mathias?", description = "Master Mathias Shaw is the leader of the Alliance intelligence organization known as SI:7. And apparently, he is now a dreadlord.\n\nOr rather, a very clever dreadlord has taken his place while he is being held captive somewhere.\n\nIt is imperative that we reveal this imposter to the new king of Stormwind. If we fail to do so, then the Alliance will surely be eaten alive from within and the Burning Legion will win this war for a certainty.", objectives = "Use the Scouting Map and complete the \"Where In the World is Mathias Shaw?\" missions.", completion = "Well, now we know that our SI:7 friend is being held at Felsoul Hold in Suramar. Not sure why we didn't check there first.\n\nI trust that you already have a general plan for how to retrieve him? I know that I do. Perhaps we can put our heads together." }
WordHunterWoW_QuestEN[43470] = { title = "Pruning the Garden", description = "In a very real sense, the Uncrowned are gardeners. We snip and trim here and there. One clipping of a single branch may seem nonsensical until you step back and look at the garden as a whole.\n\nOn the greater theater of the Broken Isles, we must act decisively. The forces that arrayed against Azeroth are moving quickly. We need to prune some very ugly flowers to make our garden beautiful again, wouldn't you agree, {name}?", objectives = "Complete 10 World Quests.", completion = "There, now that is much better. I would say that our garden is much more beautiful." }
WordHunterWoW_QuestEN[43471] = { title = "The Historians", description = "{name}, each year I visit Stormwind to help adventurers like you reflect on our shared history. While our eyes must always be trained on the future, we must be mindful of our past. Come visit me in the Stormwind Royal Library and we can speak more.", objectives = "Meet with Historian Llore in the Royal Library of Stormwind.", completion = "<name>, you're here. You must have received my letter." }
WordHunterWoW_QuestEN[43472] = { title = "The Historians", description = "{name}, each year I visit Orgrimmar to help adventurers like you reflect on our shared history. While our eyes must always be trained on the future, we must be mindful of our past. Come visit me in the Valley of Spirits and we can speak more.", objectives = "Meet with Historian Ju'Pa in the Valley of Spirits of Orgrimmar.", completion = "<name>, you're here. You must have received my letter." }
WordHunterWoW_QuestEN[43473] = { title = "Experimental Potion: Test Subjects Needed", description = "", objectives = "Want to earn a few quick coins? I need subjects to try one of my potions.\n\nThis one gets its unique aroma from frog eyes, frog hearts... wait a minute. Let me check the ingredient list here.\n\nMm-hmm, mm-hmm, OK, yeah.\n\nThis is pretty much just liquid frogs. Bottoms up!" }
WordHunterWoW_QuestEN[43474] = { title = "Experimental Potion: Test Subjects Needed", description = "", objectives = "Want to earn a few quick coins? I need subjects to try my newest potion.\n\nUnfortunately, I can't taste this one myself because it contains a few ingredients that I'm allergic to. Drinking this would be incredibly toxic to me. In fact, as far as I'm concerned, this is just one big bottle of poison.\n\nDrink up!" }
WordHunterWoW_QuestEN[43475] = { title = "Experimental Potion: Test Subjects Needed", description = "", objectives = "Want to earn a few quick coins? I need subjects to try this potion.\n\nI spent most of my development time focusing on the potion's effects, and not a lot on its... pleasantness. You may have to ignore the taste, smell, mouthfeel, and appearance.\n\nActually, I think I heard a few SOUNDS coming from this particular potion... you should ignore those, too.\n\nCheers!" }
WordHunterWoW_QuestEN[43476] = { title = "Experimental Potion: Test Subjects Needed", description = "", objectives = "Want to earn a few quick coins? I need a new subject to try one of my favorite potion recipes.\n\nI have to admit, the last few times I tried to make a potion like this, it didn't work out so well for the test subjects. In fact, this is why I have to pay people to drink my potions now.\n\nPlease enjoy." }
WordHunterWoW_QuestEN[43477] = { title = "Experimental Potion: Test Subjects Needed", description = "", objectives = "Want to earn a few quick coins? I need test subjects to try my newest potion.\n\nI've had several requests for vegetarian potions. You'd be surprised how many potions have meat in them!\n\nTo compensate for the complete lack of carcasses in this potion, I've had to make a few substitutions. I hope you like crushed-up bits of glass and rotten fish guts!\n\nFish aren't animals, right?" }
WordHunterWoW_QuestEN[43478] = { title = "Experimental Potion: Test Subjects Needed", description = "", objectives = "Want to earn a few quick coins? I need test subjects to drink a potion while I watch them.\n\nI've had a lot of trouble getting this potion to perform its desired effect. Mostly it just seems to make people mad at me for making them drink it.\n\nGo on, then. Drink up." }
WordHunterWoW_QuestEN[43479] = { title = "The World is Not Enough", description = "Now that we have pruned the garden, it is time to dig up the rotting tree stump in the middle.\n\nPut another way, we need to make sure to keep the forces of chaos from overwhelming the Broken Isles. Certainly others are helping in this endeavor.\n\nHowever, I am sure the target you select to eliminate will be the wisest from the standpoint of the Uncrowned.", objectives = "Complete any 1 \"Rare Elite\" World Quest designated by a blue exclamation mark surrounded by a gold dragon on the area maps.", progress = "And have you dug up that tree stump yet, <name>?", completion = "A wise choice of targets indeed. The Uncrowned are fortunate to count you amongst our ranks, Mister <name>." }
WordHunterWoW_QuestEN[43480] = { title = "Huk'roth the Houndmaster", description = "", objectives = "" }
WordHunterWoW_QuestEN[43481] = { title = "Vignette: Arcanist Lylandre", description = "", objectives = "" }
WordHunterWoW_QuestEN[43483] = { title = "Fel Annihilation", description = "", objectives = "" }
WordHunterWoW_QuestEN[43484] = { title = "Vignette: Rauren", description = "", objectives = "" }
WordHunterWoW_QuestEN[43485] = { title = "A Burning Distraction", description = "We're going to need a distraction if we are to rescue Mathias Shaw from where he's being held captive in Felsoul Hold.\n\nA big one.\n\nExplosives placed in a few key locations should do nicely. Noggenfogger is playing nice and has donated some bombs to the cause. He might be trying to smooth over relations due to his earlier extortion.\n\nI can have someone go ahead and mark the best locations. You want to do the honors?", objectives = "Place the Noggenfogger Boom Bombs on your way through Felsoul Hold and then trigger the Detonator to set them off.", progress = "As soon as you set all of the explosives and push the button, we will proceed.", completion = "That was a big distraction!" }
WordHunterWoW_QuestEN[43486] = { title = "Cracking the Codex", description = "I have been studying the Codex of Command that you recovered from Faronaar.\n\nIt is important to Balnazzar, but WHY? What does it say? I'm sure we could gain valuable knowledge if we could just crack this code.\n\nI have a friend who might be able to help us: a priestess named Delas Moonfang. She has been studying Eredun, the language of the demons.\n\nTake the sigil to her in Dalaran. Tell her I sent you.", objectives = "Speak to Delas Moonfang in Dalaran.", completion = "Aponi sent you? How is she? It is hard to keep in touch with friends in these times." }
WordHunterWoW_QuestEN[43487] = { title = "Assault on Violet Hold: The Fel Lexicon", description = "I have been studying the language of the demons, but it has been difficult to get my hands on written material.\n\nI have heard rumor of a book called the Fel Lexicon, written by an ancient scholar who spoke both eredun and draenei. If I could just get my hands on that book, I could learn so much!\n\nI heard that this book might be in the hands of a powerful prisoner inside the Violet Hold.\n\nBring me this book, and my work here will go much faster.", objectives = "Collect a Fel Lexicon from a powerful prisoner inside Violet Hold.", progress = "I am fairly adept in twelve different languages, and I hope to add more to the list.", completion = "Yes, I believe this is it! Just look at it, <name>. I will put this knowledge to good use." }
WordHunterWoW_QuestEN[43488] = { title = "Blood of Our Enemy", description = "I have seen demonic artifacts before, {name}.\n\nLegion sigils will only reveal themselves in the presence of demon blood.\n\nI sense that time is of the essence. Bring me a large quantity of demon blood, so that I may translate the book as soon as you retrieve it.", objectives = "Send your champions on \"Blood of Our Enemy\" missions against the Burning Legion and collect 5 Flasks of Demon Blood.", progress = "The last time, I tried to use a living demon. It ended rather poorly... for the demon.", completion = "Yes, this will do nicely." }
WordHunterWoW_QuestEN[43489] = { title = "To Felblaze Ingress", description = "I have sobering news, Highlord.\n\nWe have had no word from Chieftain Aponi Brightmane, young Arator, or priestess Delas Moonfang since they departed for Felblaze Ingress.\n\nWe need to know what happened to them.\n\nWe fear the worst.", objectives = "Find Aponi Brightmane at Felblaze Ingress in Azsuna.", completion = "<The book is written in Aponi's hand. What happened here?>" }
WordHunterWoW_QuestEN[43490] = { title = "Aponi's Trail", description = "<The book is missing several pages. Nearby, you can see signs of a struggle.>\n\n<If you can seek the missing pages on the nearby demons, perhaps you could learn what fate befell your allies.>", objectives = "Find 8 pages of Aponi's journal, then use them to track her down.", progress = "I've never been so happy to see you, Highlord.", completion = "Thank the Light, Highlord. I didn't want to give up hope." }
WordHunterWoW_QuestEN[43491] = { title = "Allies of the Light", description = "Both Arator and Delas are still somewhere on this forsaken rock, as well as many of our other allies.\n\nWe cannot leave them, {name}.", objectives = "Save 5 Silver Hand Knights or Conclave Priests, and rescue Arator the Redeemer and Delas Moonfang.", completion = "I already heard of your heroism from Aponi Brightmane, Highlord. Thanks to you, many lives were saved." }
WordHunterWoW_QuestEN[43492] = { title = "Champion: Aponi Brightmane", description = "", objectives = "Highlord, I owe you my life and my thanks. You live by the Light, as my Sunwalkers believe.\n\nIt is an honor to fight by your side, and with your permission, I would like to continue fighting for the Order of the Silver Hand." }
WordHunterWoW_QuestEN[43493] = { title = "Black Rook Hold: Lord Ravencrest", description = "Highlord, news has reached us of a Legion presence at Black Rook Hold.\n\nIt is rumored that the night elf commander, Kur'talos Ravencrest, amasses an enormous army behind the fortress walls.\n\nTake a group of your most powerful allies, Highlord, and investigate these stories. Lord Ravencrest was a formidable general during Azshara's reign, and if the reports are true, then we must know more.", objectives = "Defeat Lord Kur'talos Ravencrest in Black Rook Hold.", progress = "It is vital that we stay on top of the Legion's movements. At any moment, they could attack.", completion = "Incredible, Highlord. With the threat at Black Rook Hold contained, we can focus efforts on other areas." }
WordHunterWoW_QuestEN[43494] = { title = "Silver Hand Knights", description = "Good news, Highlord! We have recruited a paladin trainer named Commander Born.\n\nHe is a hard teacher, but has trained some of the greatest paladin knights in recent times. We are lucky to have his services.\n\nGo speak to him, and train a squad of Silver Hand Knights.", objectives = "Speak to Commander Born.", completion = "Wonderful! These knights will serve the order well." }
WordHunterWoW_QuestEN[43495] = { title = "Vignette: Cadraeus", description = "", objectives = "" }
WordHunterWoW_QuestEN[43496] = { title = "The Power Within", description = "My apologies for the unannounced intrusion, {name}. Do you have a moment?\n\nThe power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away within. Perhaps even a new form entirely!\n\nThe very thought demands we find out for sure.\n\nYou are familiar with the ancient blue dragon Senegos in Azsuna, yes? Meet me at his repose once you are able and we will discuss more.", objectives = "Meet Archmage Kalec at Azurewing Repose in Azsuna.", completion = "Senegos has generously offered us his assistance in the journey ahead.\n\nA truly kind soul." }
WordHunterWoW_QuestEN[43497] = { title = "Legion 110 A", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43498] = { title = "Legion 110 A", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43499] = { title = "Legion 110 H", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43500] = { title = "Legion 110 H", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43501] = { title = "The Power Within", description = "My apologies for the unannounced intrusion, {name}. Do you have a moment?\n\nThe power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away within. Perhaps even a new form entirely!\n\nThe very thought demands we find out for sure.\n\nThe ancient blue dragon in Azsuna known as Senegos lays dying and is key to our journey. You must aid him - I will meet you in his domain as soon as I am able.", objectives = "Complete the \"Defending Azurewing Repose\" storyline in Azsuna, then meet Archmage Kalec at Azurewing Repose.", completion = "Senegos has generously offered us his assistance in the journey ahead.\n\nA truly kind soul." }
WordHunterWoW_QuestEN[43502] = { title = "A Change of Seasons", description = "It is time.\n\nThe arcan'dor is preparing to mature. With a final burst of growth, this gift will be fully realized.\n\nWe must make ready the leyline feed.", objectives = "Speak with Arcanist Valtrois.", completion = "It would seem our tree is quite thirsty." }
WordHunterWoW_QuestEN[43503] = { title = "The Power Within", description = "Do you have a moment, Conjurer?\n\nThe power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away deep within. Perhaps even a new form entirely!\n\nThe very thought demands we find out for sure.\n\nYou are familiar with the ancient blue dragon Senegos in Azsuna, yes? Meet me at his repose once you are able and we will discuss more.", objectives = "Meet Archmage Kalec at Azurewing Repose in Azsuna.", completion = "Senegos has generously offered us his assistance in the journey ahead.\n\nA truly kind soul." }
WordHunterWoW_QuestEN[43505] = { title = "The Power Within", description = "Do you have a moment, Conjurer?\n\nThe power within your weapon has grown exponentially as you have fought the Legion, but I cannot help but wonder if there is something... more... hidden away within. Perhaps even a new form entirely!\n\nThe very thought demands we find out for sure.\n\nThe ancient blue dragon in Azsuna known as Senegos lays dying and is key to our journey. You must aid him - I will meet you in his domain as soon as I am able.", objectives = "Complete the \"Defending Azurewing Repose\" storyline in Azsuna, then meet Archmage Kalec at Azurewing Repose.", completion = "Senegos has generously offered us his assistance in the journey ahead.\n\nA truly kind soul." }
WordHunterWoW_QuestEN[43506] = { title = "Black Rook Hold: Greater Power", description = "The raw power of the runestones will allow Hymdall to temporarily open a tear into demonic worlds, but it's not enough.\n\nThe Legion hides its presence in far away worlds with dark magic. Bring a greater runestone so that Hymdall can hone in on our enemies across the cosmos.", objectives = "Defeat Lord Kur'talos Ravencrest and retrieve a Greater Demonic Runestone from Dantalionax in the Black Rook Hold Dungeon.", progress = "Do you bring the runestone we require, <name>?", completion = "It is done. Let us prepare the Valarjar for glorious battle!" }
WordHunterWoW_QuestEN[43507] = { title = "Looted Priest Altar", description = "", objectives = "" }
WordHunterWoW_QuestEN[43508] = { title = "The Captive Spymaster", description = "We must move swiftly while the distraction is working. Mathias Shaw is being held in the lower levels of the Halls of the Eclipse directly to the south.\n\nQuickly, {name}, we must go!", objectives = "Follow Taoshi into the Halls of the Eclipse to where Mathias Shaw is being held captive.", completion = "Hurry, <name>. We must get him out of here before the demons raise the alarm." }
WordHunterWoW_QuestEN[43509] = { title = "Halls of Valor: Odyn's Challenge", description = "Odyn himself sends a message. He and his warriors await worthy contenders within the Halls of Valor.\n\nDefeat the champions of the Halls of Valor, and claim glory.", objectives = "Defeat Odyn in the Halls of Valor.", completion = "Were you able to overcome Odyn's challenge?" }
WordHunterWoW_QuestEN[43510] = { title = "Seal of Fate: Class Hall", description = "", objectives = "" }
WordHunterWoW_QuestEN[43511] = { title = "Kalec Arrives", description = "", objectives = "" }
WordHunterWoW_QuestEN[43512] = { title = "Ana-Mouz", description = "", objectives = "" }
WordHunterWoW_QuestEN[43513] = { title = "Na'zak the Fiend", description = "", objectives = "" }
WordHunterWoW_QuestEN[43514] = { title = "A Vainglorious Past", description = "The Heart's magic is attuned to Azshara's elite through powerful warding spells. If we tried to tap into its power now we would be met only with our own demise.\n\nHowever, there may be a way we can bypass the wards.\n\nPrince Farondis and his court were once a part of Azshara's empire, and still hold on to keepsakes of their sordid past. Among these is sure to be a Vainglorious Draught, said to further bind the queen's followers to her will.\n\nSee if you can convince the court to part with a bottle.", objectives = "Obtain a Vainglorious Draught from Veridis Fallon.", progress = "It may take some effort to convince Farondis' people to part with the draught; some among them still cling desperately to their past lives.", completion = "Well done. We can use this to disable the magic protecting the Heart." }
WordHunterWoW_QuestEN[43517] = { title = "Darkheart Thicket: Fallen Power", description = "Once we have the proper implements we can use the Heart to infuse great power into your artifact. We need only a source.\n\nDeep within the Darkheart Thicket lies the ancient Oakheart, once a great and mighty protector of Shaladrassil. He has regrettably fallen to the nightmare like so many of his kin.\n\nAs the darkness within him has taken root, an essence of the corruption has manifested. I ask that you recover the essence so that we may draw from its power, and put noble Oakheart to rest.", objectives = "Recover a Corrupted Essence from Oakheart and defeat the Shade of Xavius in Darkheart Thicket on Mythic difficulty.", progress = "You have the essence?", completion = "The ancient is at peace once more.\n\nMay his sacrifice not be in vain." }
WordHunterWoW_QuestEN[43518] = { title = "Tempering Darkness", description = "I do not doubt Senegos' plan, but I do have some concerns about the Heart's volatility, especially when combined with nightmare energy.\n\nDespite its name, Blood of Sargeras is often used as a tempering agent by master craftsmen. I believe it would work for our ritual as well.\n\nYou should keep an eye out for it during your travels - we'll need a substantial amount to ensure that everything goes smoothly.", objectives = "Obtain 5 Blood of Sargeras.", progress = "It can be difficult to extract properly, but I do not wish to leave anything to chance.", completion = "Fantastic! This will do quite nicely." }
WordHunterWoW_QuestEN[43519] = { title = "Lucid Strength", description = "We have everything we need, {name}.\n\nOnce you are ready, raise your artifact and channel its energy upon the Heart of Zin-Azshari to safely absorb the power stored within the nightmare essence.\n\nI will use the blood you provided to make sure the ritual stays safely contained.", objectives = "Absorb the power from the Corrupted Essence using the Heart of Zin-Azshari.", progress = "This is but the first step in unlocking the true potential hidden away deep within your artifact, but it is an exciting milestone nonetheless.", completion = "Well done! Everything went as planned." }
WordHunterWoW_QuestEN[43520] = { title = "The Emerald Nightmare: In Nightmares", description = "We must do what we can to ensure that the Nightmare never again festers within the Emerald Dream.\n\nThe aberration known as Il'gynoth lies at the heart of the corruption - a living, writhing manifestation of the horrors you will encounter at every turn of your journey.\n\nI ask that you ensure its destruction, along with the Nightmare Lord himself... Xavius.\n\nOnce the deeds have been done, bring a small piece of each to me. We can study them to figure out just how the Nightmare grew so quickly.", objectives = "Obtain a Deathglare Iris and the Horn of the Nightmare Lord from the Emerald Nightmare on Normal difficulty or higher.", progress = "Is the deed done?", completion = "That is... far more than we needed.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[43521] = { title = "The Emerald Nightmare: Essence of Power", description = "Now that we have a better understanding on the Heart's capabilities, it is time we tap into its true potential.\n\nIn the Emerald Nightmare you will find creatures that should not be; monsters that defy all that the Dream stands for.\n\nAll that the green flight itself stands for.\n\nEach of these fiends carry within them corrupted essence, as Oakheart did, but far more potent. Gather all that you can, and we will turn their corruption against them.", objectives = "Collect 10 Corrupted Essence from the Emerald Nightmare on Normal difficulty or higher.", progress = "The task before you is not simple, but I have faith in your abilities.", completion = "Your bravery rivals that of my own kind.\n\nWell done." }
WordHunterWoW_QuestEN[43522] = { title = "Essential Consumption", description = "As before, {name}, once you are ready raise your artifact and channel its energy upon the Heart of Zin-Azshari and we will unleash the power of the essence you gathered.\n\nDo not worry - we still have enough of the blood you gathered to ensure the ritual remains stable.", objectives = "Absorb the combined power of the Corrupted Essences using the Heart of Zin-Azshari.", progress = "After all you have done for my flight, this is but a small favor in return.", completion = "That is all I can do for you, little one. If you seek more power, you must look elsewhere." }
WordHunterWoW_QuestEN[43523] = { title = "Repaid Debt", description = "The Moon Guard fought against the Legion many years ago, during the War of the Ancients. Their intimate knowledge of our enemies would be invaluable to our cause.\n\nThey have remained in Shal'Aran since you saved Thalrenus and his kin. Shall we pay them a visit and see what they can do?", objectives = "Meet Archmage Kalec inside Shal'Aran in Suramar.", completion = "Let us speak with Thalrenus and discuss our plan of action." }
WordHunterWoW_QuestEN[43524] = { title = "Court of Stars: Literary Perfection", description = "Out of all the books, why that one?! Oh, Mother Moon, I am but a trusting fool.\n\nI apologize, you have no idea what I'm going on about.\n\nI lent my first edition copy of \"Wards, Sigils, and the Nightborne Way\" to a dear friend - well, former friend, I should say - just before the betrayal.\n\nAs fate would have it, there is an incantation in that book that I will need for my part of the ritual.\n\nPlease retrieve it if you can, but be careful - it is quite valuable!", objectives = "Find Lothrius' first edition copy of \"Wards, Sigils, and the Nightborne Way\" in the Court of Stars on Mythic difficulty.", progress = "Did you find it? Oh, please tell me you found it!", completion = "That's the one! Oh, thank you, <name>. Thank you!" }
WordHunterWoW_QuestEN[43525] = { title = "Vault of the Wardens: Borrowing Without Asking", description = "The elusive Wardens run an immense secret prison facility deep underneath the mountains of Azsuna housing all manner of terrible creatures.\n\nPerhaps... 'used to run' is more accurate.\n\nThis presents us with a unique opportunity. The wardens used powerful containment crystals to encase each prisoner in their cell. If any of them still remain intact, we could use one to safely contain the Heart's power.\n\nThey certainly won't be needing them.", objectives = "Recover a Containment Crystal from the Vault of the Wardens on Mythic difficulty.", progress = "Any luck?", completion = "Excellent. This will work quite well." }
WordHunterWoW_QuestEN[43526] = { title = "A True Test", description = "Vizuul's runebindings are more potent than I had anticipated. Not a bad thing - more power is certainly welcome - but there's certainly more potential for catastrophe if the spell matrix somehow becomes unstable.\n\nWe should be able to safely contain the fel energy within the containment field using the eon winder you recovered... but keep an eye open just in case.", objectives = "Absorb the power from the Twisted Runebindings using the Heart of Zin-Azshari.", progress = "I'm sure we'll be able to keep everything stable.", completion = "I'm... so sorry, <name>. I was so sure that would work..." }
WordHunterWoW_QuestEN[43527] = { title = "Saving the Guard", description = "The Moon Guard were once among the most powerful sorcerers on Azeroth. Most assumed their ranks demolished after the War of the Ancients, but it seems they have managed to survive in their ancient stronghold in Suramar!\n\nI believe they could be valuable allies in our quest if they still oppose the Legion.\n\n{name}, if you can save what remains of the Guard, I will work to convince the Council of Six to lend us additional aid.", objectives = "Complete the \"Moon Guard Stronghold\" storyline in Suramar, then meet Archmage Kalec in Shal'Aran.", completion = "It seems we have gained new allies. Let us figure out a plan of action." }
WordHunterWoW_QuestEN[43528] = { title = "Planning the Assault", description = "Thanks to your tireless efforts the Heart of Zin-Azshari is ready to withstand the full power of the Legion. The final destination in our journey has stood defiantly in front of us from the moment we began - the Nighthold, now home to none other than Gul'dan himself.\n\nWe just need a way inside.\n\nI am working fervently with the rest of the Council of Six to secure an entrance. Once we have, we should reunite with the Moon Guard in Shal'Aran - we still have need of their skills.", objectives = "Await the opening of the Nighthold, then meet Archmage Kalec in Shal'Aran.", completion = "We've found a back entrance into the Nighthold that should provide some relief from the armies at the main gate.\n\n'Some' being key." }
WordHunterWoW_QuestEN[43530] = { title = "The Nighthold: Delusions of Grandeur", description = "Grand Magistrix Elisande and her cohorts have lost their minds - they truly believe that allying themselves with the Legion will end in anything but their own demise!\n\nThey are too far gone to save, I'm afraid, but they still have powerful items that we can use to help us infuse the Heart of Zin-Azshari with their power.\n\nIn your assault on the Nighthold, ensure you recover the mad construct Trilliax's power core, as well as the spellbook of the Grand Magistrix herself.\n\nGood luck.", objectives = "Collect the core of Trilliax and Grand Magistrix Elisande's Millennia Tome in the Nighthold on Normal difficulty or higher.", progress = "I ask more of you than I wish, but there is no other way.", completion = "<Thalrenus' eyes widen at the sight of the Millenia Tome.>\n\nIf Elisande has seen reason... perhaps there is still hope for the Guard after all." }
WordHunterWoW_QuestEN[43531] = { title = "The Nighthold: Into the Nighthold", description = "Our work is very nearly complete. Now that the Heart can safely absorb power from fel magic, we need the strongest sources of it that we can get our hands on.\n\nGul'dan has called the nightborne's elite back to the Nighthold to aid him. The storm of fel energy above the palace has seeped into the very fabric of their being, even making its way into the crystallized pieces of the Nightwell that many carry with them.\n\nThose shards are exactly what we need, {name}. Save as many as you can in your assault.", objectives = "Collect 8 Nightshards from the Nighthold on Normal difficulty or higher.", progress = "How many Nightshards were you able to retrieve?", completion = "<Kalec sifts through the pile of Nightshards.>\n\nYes, these are perfect! There's just one more thing we need." }
WordHunterWoW_QuestEN[43532] = { title = "The Nighthold: Darkness Calls", description = "Before we perform the ritual there is one last thing I must ask of you, {name}.\n\nYou must finally bring Gul'dan to justice.\n\nNo more of his lies, his deceits, or his trickery. None of it can save him now.\n\nTake one of his conjured eyes when you're done. Using his power for good will be a fitting end.", objectives = "Bring one of Gul'dan's eyes to Archmage Kalec on Normal difficulty or higher.", progress = "Is the deed done?", completion = "Let us not waste another moment." }
WordHunterWoW_QuestEN[43533] = { title = "Balance of Power", description = "At long last, it is time to reap the fruits of your labors.\n\nLothrius tells of a place deep in the former Moonguard Stronghold used to infuse new Guards with immense power. It will be the perfect place to tap into and augment the power of the Nightshards you gathered.\n\nGather your effects and meet me there when you are ready, and we will use the Heart to finally reveal the great power within your artifact.", objectives = "Absorb the combined power of the Nightshards and the Eye of Gul'dan using the Heart of Zin-Azshari at the Lunar Crucible.", progress = "This is a truly momentous occasion.", completion = "Your artifact's new form is even more fantastic than I imagined.\n\nPlease, take what remains of the Heart as a token of my gratitude for such a marvelous adventure - there is still a fair bit of power left inside it." }
WordHunterWoW_QuestEN[43534] = { title = "Blood of Sargeras", description = "We will require a powerful reagent to bind the magic in our weapons and armor. A rare material that will do just the trick is Blood of Sargeras.\n\nWe will need a plentiful quantity. Bring me whatever you can muster.", objectives = "Collect 3 Blood of Sargeras.", progress = "Have you acquired any Blood of Sargeras?", completion = "Yes, this is just what we need to complete our preparations. These must have been difficult to come by. Thank you, Highlord." }
WordHunterWoW_QuestEN[43535] = { title = "Translation: Danger!", description = "<Delas smears fel blood across the lexicon's pages. Alien sigils blaze forth above the paper. She scribbles them down furiously.>\n\nMy goodness... these are detailed records of the Legion invasion force at Felblaze Ingress. They are planning to open a portal directly to their demon world of Niskara! This is quite serious - we need to alert your allies at once.\n\nIf you are going back to Light's Hope Chapel, could I accompany you? I would like to offer my services.", objectives = "Speak to Aponi Brightmane at the Sanctum of Light.", progress = "Did you bring back the translation?", completion = "Thank you for bringing Delas with you, <name>. I knew she could help us." }
WordHunterWoW_QuestEN[43539] = { title = "Salanar the Horseman", description = "The Four Horsemen will need perfect steeds. This is no simple task.\n\nFor the next step of our campaign, I have organized a mission to the Realm of Shadows.\n\nThe goal of the mission is to find Salanar the Horseman, leader of the Dark Riders, and summon him to Acherus.\n\nThe mission is currently waiting your assignment.", objectives = "Complete the \"Salanar the Horsemen\" mission.", completion = "The Ebon Blade champions sent to the Realm of Shadows have successfully returned to Acherus.\n\nSalanar the Horseman will be arriving shortly to begin preparations for the dread steeds. You should meet with him when he arrives." }
WordHunterWoW_QuestEN[43540] = { title = "The Mind of the Enemy", description = "The demon jailors spoke of an upcoming invasion. Their army is gathering for something big, and it worries me greatly.\n\nLet us find whatever information we can about their plans.", objectives = "Find the Legion Intelligence, the Star Map, the Image of Velen, then slay Brood Queen Aramis.", completion = "The Legion has plans to attack the priests' center of command? It is critical that you discovered this information in time, Highlord.\n\nIt makes sense that the Legion would target Prophet Velen and his followers. We cannot allow Balnazzar to succeed." }
WordHunterWoW_QuestEN[43541] = { title = "United As One", description = "I am glad you returned safely, Highlord. Delas Moonfang has also arrived with representatives of the Conclave.\n\nThe priests have come to discuss Netherlight Temple, their seat of power, hidden deep within the Twisting Nether.\n\nAs you have both discovered, the Legion has been searching for them for quite some time, and now... they have found them.\n\nThe Silver Hand has agreed to hear their words. Would you join them now, Highlord?", objectives = "Speak to Delas Moonfang and hear the council of war.", progress = "Delas has come on behalf of the Conclave.", completion = "I believe you have chosen well, Highlord. We will help defend Netherlight Temple and lay a trap for Balnazzar.\n\nThe priests of the Conclave are formidable allies. With our combined strength, we may just have a chance against Balnazzar." }
WordHunterWoW_QuestEN[43542] = { title = "Vignette: Tideclaw", description = "", objectives = "" }
WordHunterWoW_QuestEN[43545] = { title = "Black Rook Hold: The Lord of Black Rook Hold", description = "While investigating the remains of Black Rook Hold, our Champions were ambushed!  The Lord of the Rook appears to have allied himself with the Legion.\n\nWe need your assistance to defeat his growing army, and bring him down.", objectives = "Defeat Lord Kur'talos Ravencrest in Black Rook Hold.", completion = "Were you able to defeat Lord Ravencrest?" }
WordHunterWoW_QuestEN[43546] = { title = "The Emerald Nightmare: Il'gynoth", description = "Our Champions have discovered the source of the corruption.  The Emerald Dream has been infested by the Legion and if we don't put our efforts towards stopping them, this will be only the beginning of the corruption.  It must be stopped here.", objectives = "Defeat Il'gynoth in the Emerald Nightmare.", progress = "How are you finding the challenges of the Emerald Nightmare?", completion = "Were you able to overcome the Emerald Nightmare?" }
WordHunterWoW_QuestEN[43547] = { title = "The Emerald Nightmare: Il'gynoth", description = "Our Champions have discovered the source of the corruption.  The Emerald Dream has been infested by the Legion and if we don't put our efforts towards stopping them, this will be only the beginning of the corruption.  It must be stopped here.", objectives = "Defeat Il'gynoth in the Emerald Nightmare.", progress = "How are you finding the challenges of the Emerald Nightmare?", completion = "Were you able to overcome the Emerald Nightmare?" }
WordHunterWoW_QuestEN[43548] = { title = "The Emerald Nightmare: Il'gynoth", description = "Our Champions have discovered the source of the corruption.  The Emerald Dream has been infested by the Legion and if we don't put our efforts towards stopping them, this will be only the beginning of the corruption.  It must be stopped here.", objectives = "Defeat Il'gynoth in the Emerald Nightmare.", progress = "How are you finding the challenges of the Emerald Nightmare?", completion = "Were you able to overcome the Emerald Nightmare?" }
WordHunterWoW_QuestEN[43549] = { title = "The Emerald Nightmare: Il'gynoth", description = "Our Champions have discovered the source of the corruption.  The Emerald Dream has been infested by the Legion and if we don't put our efforts towards stopping them, this will be only the beginning of the corruption.  It must be stopped here.", objectives = "Defeat Il'gynoth in the Emerald Nightmare.", progress = "How are you finding the challenges of the Emerald Nightmare?", completion = "Were you able to overcome the Emerald Nightmare?" }
WordHunterWoW_QuestEN[43550] = { title = "Court of Stars: Into the Court of Stars", description = "The weather is perfect for a party, isn't it?\n\nTravel to the Court of Stars, where the Grand Magistrix herself may appear among her nobles to reassure them of the need for all the Legion patrols.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Defeat Advisor Melandrus in Court of Stars." }
WordHunterWoW_QuestEN[43551] = { title = "Darkheart Thicket: Into Darkheart Thicket", description = "Beneath the boughs of Shaladrassil, Xavius extends his power to twist and torment the once-pure druid grove. \n\nNot only this, but Xavius has taken a prize from among the druids, and his revenge will be slow and painful. We should go to Darkheart Thicket and stop his wicked plans.", objectives = "Defeat the Shade of Xavius in Darkheart Thicket.", progress = "How are you finding the Darkheart Thicket?", completion = "Were you able to overcome Darkheart Thicket?" }
WordHunterWoW_QuestEN[43552] = { title = "Eye of Azshara: Into the Eye of Azshara", description = "Our investigation found that the naga, under the orders of Queen Azshara herself, are preparing to summon a powerful entity to unleash Azshara's power across the Broken Isles.\n\nTravel to the Eye of Azshara, and put a stop to the ritual.", objectives = "Defeat the Wrath of Azshara in Eye of Azshara.", completion = "Were you able to overcome Eye of Azshara" }
WordHunterWoW_QuestEN[43553] = { title = "Maw of Souls: Into the Maw of Souls", description = "Our scouts report that the vrykul damned are forced to sail aboard the Naglfar, a ship built of death.\n\nTravel to the Maw of Souls and confront Helya, before she collects any more poor, unfortunate souls.", objectives = "Defeat Helya in Maw of Souls.", completion = "Were you able to overcome Maw of Souls?" }
WordHunterWoW_QuestEN[43554] = { title = "Neltharion's Lair: Into Neltharion's Lair", description = "Our scouts found that not only have the drogbar obtained a Titan relic, but also they've amassed an army large enough to threaten the overworld.\n\nDelve underground and stop the Underking before he can unleash the might of his drogbar army.", objectives = "Defeat Dargrul in Neltharion's Lair.", completion = "Were you able to overcome Neltharion's Lair?" }
WordHunterWoW_QuestEN[43555] = { title = "The Arcway: Into the Arcway", description = "The Arcway is even more vast than we thought, and holds many dangers. If we have any hope of taking the city, we must first see to the underground.\n\nEnter The Arcway and clear out any, and all enemies.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Defeat Advisor Vandros in The Arcway." }
WordHunterWoW_QuestEN[43556] = { title = "Vault of the Wardens: Into the Vault of the Wardens", description = "It's worse than we thought within the Vault of the Wardens. The prisoners have become the jailers, and have completely taken over the vault. However, our intelligence reports that Cordana Felsong herself may be there.\n\nEnter the Vault of the Wardens and cleanse the place of evil.", objectives = "Defeat Cordana Felsong in Vault of the Wardens.", completion = "Were you able to overcome Vault of the Wardens?" }
WordHunterWoW_QuestEN[43557] = { title = "Assault on Violet Hold: Into the Violet Hold", description = "The Violet Hold contains some of the Lich King's most powerful servants, and is at risk of being overrun by Legion agents. We must go there and thwart the demons before any of the prisoners can be set free.", objectives = "Defeat the leader of the Assault on Violet Hold.", completion = "Were you able to overcome the Assault on the Violet Hold?" }
WordHunterWoW_QuestEN[43558] = { title = "Bindings of the Windlord", description = "With Thunderaan risen again as the lord of Skywall, there may indeed be an arrangement you can make in exchange for those wretched implements. But one binding is of no use on its own.\n\nReturn to me with both bindings, and with powerful enough ore to bind them, and I will arrange your audience with Thunderaan the Windlord.", objectives = "Retrieve both Bindings of the Windlord and 10 Infernal Brimstone.", progress = "Yes, <race>?", completion = "And so you return with the bindings in hand. The Firelord shall be very displeased to have lost these." }
WordHunterWoW_QuestEN[43560] = { title = "Audience with the Windlord", description = "I have kept my promise. Thunderaan the Windlord awaits.\n\nKnow that if betrayal is in your heart, the Windlord will not be deceived. Be silent, and perhaps your audience shall be a fortunate one.", objectives = "Witness Thunderaan.", completion = "The bindings now belong to me. When the time comes, the Firelord shall be imprisoned as I once was. But that time is not now.\n\nYour reward is this, a small fragment of my power. Unleash it upon your blades, <race>, and you shall have what you seek." }
WordHunterWoW_QuestEN[43561] = { title = "I Believe I Can Fly!", description = "Let's not bother explaining how this happened, just know that I have the plan of all plans to escape this... this... <Looks over his hand-crafted outfit, then quickly glances to a pile of droppings nearby.>\n\nThis place stinks! But you can help!\n\nThese feathers here will help craft my escape plan. If you wouldn't mind, I'm sure there's enough for the both of us!", objectives = "Collect 6 Molted Feathers for Snicarus Dungleflight." }
WordHunterWoW_QuestEN[43562] = { title = "Giving It All We've Got", description = "The arcan'dor is drawing incredible amounts of energy.\n\nEven with the leyline feed at full capacity, we may not have the power.\n\nLet us first ensure that all potential leyline conduits connecting to Shal'Aran are active.\n\nThen I can attempt to amplify the output and hopefully satisfy this insufferable plant.", objectives = "Activate all of the leyline feeds in Suramar, then speak with Valtrois.", progress = "We must activate all of the leyline feeds in Suramar before attempting the spell.", completion = "We must take drastic measures." }
WordHunterWoW_QuestEN[43563] = { title = "Ephemeral Manastorm Projector", description = "Oculeth's theory is sound. Reckless, but sound.\n\nA small warp-field could trap and excite ambient mana in the conduit, thus creating a manastorm similar to when the arcan'dor fell out of balance.\n\nI can build a device to generate the warp-field, but I need materials.\n\nSpecifically, warp-resistant alloys - such as the armor plating of high-end security constructs in the noble district.\n\nThose constructs are deadly. If anyone owes you a favor, now is the time to call it in.", objectives = "Collect 4 Warp-Resistant Plating from Chronarch Defenders.", progress = "Without those plates, the E.M.P. would rip itself apart in seconds.", completion = "These will do nicely." }
WordHunterWoW_QuestEN[43564] = { title = "Flow Control", description = "If all goes as planned, the manastorm will cause the leyline to flare up, sending a great surge of energy through the arcway.\n\nIn order for the surge to reach Shal'Aran, we must seal off any outlets along the way. If we miss even one, the mission fails - and hundreds of people will be vaporized by the energy blow off.\n\nThalyssra had better be sure about this tree.", objectives = "Seal off the Arcway Outlets in Lunastre Lane, The Parade Grounds, and the Midnight Court.", completion = "If my map of the arcways is accurate, that should be all of the outlets we need to worry about." }
WordHunterWoW_QuestEN[43565] = { title = "Bring Home the Beacon", description = "The conduit we need is in the Arcway, and security in the Arcway has doubled since your last visit.\n\nOur only reasonable option is to teleport your strike team directly in. \n\nThis is a long-range teleport to a non-anchored destination. In other words, it will be hard.\n\nTake this beacon and survey the commons in Suramar City, then return the beacon to me so I can analyze the results. \n\nThis will help me teleport you as close as possible to the conduit!", objectives = "Use the Advanced Telemancy Beacon to survey Evermoon Commons, Evermoon Bazaar, and Siren's Vigil in Suramar City.", progress = "Imagine firing an arrow at the sky in hopes of hitting an acorn at the far end of the forest.\n\nThis teleport will be a little harder, but I think I can do it.", completion = "Excellent. With this, the chances of me teleporting you all to the bottom of the sea are much lower!" }
WordHunterWoW_QuestEN[43566] = { title = "Withered Progress", description = "", objectives = "" }
WordHunterWoW_QuestEN[43567] = { title = "All In", description = "It is time to put our plan into action.\n\nOculeth will send you, Arluin and myself into the Arcway, where we shall trigger a manastorm in the Nightflow Conduit.\n\nValtrois will stay here and prepare Shal'Aran for a massive jolt of arcane power - hopefully enough to satisfy the arcan'dor.\n\n{name}... We have a saying... \"To lead is to stand alone.\" It means only those who bear the weight of leadership can truly appreciate it.\n\nThank you for standing beside me. In truth, I do not feel alone.", objectives = "Complete the \"All In\" scenario.\n\nChief Telemancer Oculeth can begin the scenario.", completion = "Behold. The redemption of the Nightfallen." }
WordHunterWoW_QuestEN[43568] = { title = "Arcan'dor, Gift of the Ancient Magi", description = "Thousands of years ago, as the Quel'dorei were just beginning to unravel the mysteries of the arcane, a small enclave of druids met with the first of the elven magi.\n\nIn the pale moonlight, they formed an order that would seek to bring the arcane into balance - using nature itself as a vessel. Thus the arcan'dor were created.\n\nMy masters who belonged to this order have long since faded away. Yet their legacy remains.\n\nTheir gift will mend the spirit of the shal'dorei. Let them eat, and be made whole.", objectives = "Pick the Fruit of the Arcan'dor and share it with Chief Telemancer Oculeth, Arcanist Valtrois, and First Arcanist Thalyssra.", progress = "The shal'dorei must eat the fruit of the arcan'dor. It is the only way to free them.", completion = "At last... we are free." }
WordHunterWoW_QuestEN[43569] = { title = "Arluin's Request", description = "I never thought I would need to read this...\n\n<Vanthir hefts a scroll in his hand.>\n\nArluin made... plans... in the event he fell. It is not much, but I would like to honor his last request.\n\n<Vanthir hands you the scroll.>\n\nGo to the location marked on this map. Take this Arcan'dor Fruit and give it to a woman named Arluelle. Arluin was very specific that all rewards for his work be directed to her.\n\nI think he may have known what his sacrifice meant. I was wrong about him.", objectives = "Locate Arluelle and give her a piece of the Arcan'dor Fruit.", progress = "Where is Arluin?", completion = "I am not hungry any more. I can think- I will live! Oh, Arluin..." }
WordHunterWoW_QuestEN[43571] = { title = "Neltharion's Lair: Braid of the Underking", description = "Greetings, Deathlord. Years have passed since we first met, but for me it has been mere days.\n\nThe unholy bond between Horseman and steed must not be taken lightly. Power begets power, Deathlord. Never forget this fact!\n\nI can forge an inseparable bond between rider and steed, but components of great power are required.\n\nThe first item I require is the Braid of the Underking, a dark shamanic adornment passed down for generations.\n\nCurrently, it is possessed by Dargrul the Underking.", objectives = "Retrieve the Braid of the Underking from Neltharion's Lair.", progress = "Have you acquired the Braid of the Underking?", completion = "Well done, Deathlord. The cords of this braid will be used in the fashioning of reins for our steeds.\n\nI assume Dargrul was more than willing to part with it, yes?\n\n<Salanar flashes an evil grin.>" }
WordHunterWoW_QuestEN[43572] = { title = "Darkheart Thicket: The Nightmare Lash", description = "The dark steeds of the apocalypse are indomitable creatures of anguish and cruelty. They can never be tamed... only subjugated.\n\nThe next component of power we require is one born of hatred, fashioned within the Emerald Nightmare. It is known as the Nightmare Lash.\n\nThe Nightmare Lash has the power to suffocate all hope... all light... from within a living soul.\n\nThe Shade of Xavius himself carries the lash. Defeat him and bring the lash to me!\n\nI will use it to dominate the steeds of the damned!", objectives = "Retrieve the Nightmare Lash from Darkheart Thicket.", progress = "Do you have the Nightmare Lash?", completion = "At long last, the Nightmare Lash! Holding it in my hands, I can feel the truth of the legends.\n\nSuch power... such darkness... such... anguish!\n\nYes, this will do nicely." }
WordHunterWoW_QuestEN[43573] = { title = "Advancing the War Effort", description = "The quest for the Four Horsemen is of the utmost importance, however we must turn our attention to the warfront.\n\nOur continued success on the field of battle has shaken the Burning Legion and as a result, they have increased the frequency and intensity of their assaults.\n\nWe must meet the increased aggression with continued resistance!\n\nOnly then will we be able to turn our attention back to the Four Horsemen.", objectives = "Complete 10 World Quests.", progress = "How goes the war effort?", completion = "The Ebon Blade's success on the battlefield has not gone unnoticed by the Burning Legion.\n\nAs we continue the war effort, we must be mindful of increased attention from the forces of Sargeras..." }
WordHunterWoW_QuestEN[43574] = { title = "Maw of Souls: Maul of the Dead", description = "All of the necessary components have been gathered together. Soon, the unholy steeds of the damned will trample the armies of the Burning Legion.\n\nHowever, our work is not quite done. One item yet remains beyond our grasp...\n\nLurking within the depths of Helheim, the fallen queen Helya rules over the dead. In her possession is a maul, infused with the souls of countless fallen warriors.\n\nBring to me the Maul of the Dead and with it, I will forge barding so impenetrable... no demon shall break it!", objectives = "Retrieve the Maul of the Dead from Helheim.", progress = "Have you brought me the Maul of the Dead?", completion = "The legendary Maul of the Dead... it resonates with the hatred and despair of countless anguished souls. As a tool of misery, it is the embodiment of perfection." }
WordHunterWoW_QuestEN[43576] = { title = "Regroup at the Refuge", description = "I cannot think clearly in this place.\n\nEven though the moonwell is still pure, the corrupting influence of the Nightmare remains.\n\nCome, we will return to the refuge and gather our wits. Then we will continue the hunt for my husband.", objectives = "Return to Starsong Refuge.", completion = "Already my mind is sharper." }
WordHunterWoW_QuestEN[43577] = { title = "Capturing the Gateway", description = "The time has come to make our move against the Legion.\n\nThe Legion has multiple portals across the Broken Isles.\n\nShould your armies succeed in securing one while it's still active, Hymdall can use the runestones you gathered to direct it to whatever hellish world Hodir is trapped in.", objectives = "Complete the missions: Investigate Felsoul Hold, Preparing Our Arrival and Capturing the Gateway.", completion = "The Valarjar have captured the Legion's gateway at Felblaze Ingress.\n\nThe time has come to deliver a decisive blow to the enemy. We shall not wait for them to strike here!" }
WordHunterWoW_QuestEN[43578] = { title = "Looted Paladin Daily Mount", description = "", objectives = "" }
WordHunterWoW_QuestEN[43579] = { title = "Looted DK Daily Mount", description = "", objectives = "" }
WordHunterWoW_QuestEN[43580] = { title = "Vignette: Apothecary Faldren", description = "", objectives = "" }
WordHunterWoW_QuestEN[43581] = { title = "The Wisdom of Patience", description = "The horrors you braved in the thicket are only the beginning. Within the Emerald Nightmare you will face the very heart of the corruption that threatens the stability of all life on Azeroth.\n\nBut not just yet.\n\nWe have not yet managed to permeate the magic protecting Xavius' sinister realm. Once we have, however, you should return here; there is still much to be done.", objectives = "Await the opening of the Emerald Nightmare, then report back to Senegos in Azsuna.", completion = "Your next steps will be difficult, young one, and more dangerous than any threat you've faced, but they must be taken.\n\nFor the good of Azeroth." }
WordHunterWoW_QuestEN[43582] = { title = "Shalassic Park", description = "We have a Devilsaur.\n\nI think she sees you as the pack leader now. She should obey your commands.\n\nShe looks hungry. Why don't you let her off the leash a little bit?", objectives = "Ride Su'esh and defeat 50 adversaries.", completion = "That was quite the spectacle, <name>.\n\nSu'esh will be a valuable ally in the days to come. I will keep an eye on her for the time being." }
WordHunterWoW_QuestEN[43583] = { title = "Life Finds a Way", description = "", objectives = "" }
WordHunterWoW_QuestEN[43584] = { title = "Battlelord of the Valarjar", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43585] = { title = "Preparing For War", description = "We would do well to bolster our own forces before calling upon our allies to join us in the final conflict against the Legion.\n\nThere still remains much to do in the Broken Isles and victories there will give us the momentum we need to crush the enemy.", objectives = "Complete \"Aiding the Valkyra,\" \"Lost at Sea\" and \"Enslaved by Sea Giants\" missions.", progress = "Any news, <name>?", completion = "You and your armies have accomplished much. Odyn chose his commander well." }
WordHunterWoW_QuestEN[43586] = { title = "Maw of Souls: Message to Helya", description = "We cannot fight on two fronts and succeed.\n\nIf we're to give ourselves the room we need to fight off the Legion we need to deliver a decisive victory against Helya. Not her armies, not her lieutenants, but the mother of the underworld herself.\n\nGo to the Maw of Souls and defeat Helya, {name}.", objectives = "Defeat Helya inside the Maw of Souls dungeon.", progress = "Is it done?", completion = "A glorious victory! It's unfortunate that Helya survived, but she will think twice about moving against us with you leading the armies of Skyhold." }
WordHunterWoW_QuestEN[43587] = { title = "Leyline Feed: Elor'shan", description = "<The leyline feed appears to be intact and undamaged, but is not functioning. An infusion of Ancient Mana should be enough to render it operational again.>", objectives = "Infuse the leyline feed with Ancient Mana.", progress = "<The leyline feed pulses softly.>", completion = "<As you imbue the feed with the mana the structure stirs to life. Your skin tingles as the surrounding air becomes charged with arcane power.>" }
WordHunterWoW_QuestEN[43588] = { title = "Leyline Feed: Kel'balor", description = "<This feed appears to draw power from the leyline in order to become fully operational.\n\nYou should be able to imbue it with mana, but it will take a few minutes to draw enough leyline energy to accept the infusion.\n\nBeware, for creatures may notice the surge of arcane energy...>", objectives = "Defend the Leyline Feed and infuse it with Ancient Mana.", progress = "<The leyline feed pulses softly.>", completion = "<As you imbue the feed with the mana the structure stirs to life. Your skin tingles as the surrounding air becomes charged with arcane power.>" }
WordHunterWoW_QuestEN[43589] = { title = "Leyline 03", description = "", objectives = "" }
WordHunterWoW_QuestEN[43590] = { title = "Leyline Feed: Ley Station Moonfall", description = "<This leyline feed appears to be damaged. The large collector at the top is broken.\n\nThe broken piece must be around here somewhere. There are rough scuff marks on the floor that appear to be made by something larger than the creatures inside.\n\nMuch, much larger.>", objectives = "Find the Broken Leydar Dish and repair the leyline feed.", progress = "<The feed pulses softly.>", completion = "<As you place the broken piece onto the pillar and begin infusing it with mana, arcane energy begins to repair the break. It slowly begins to turn as the leyline is activated.>" }
WordHunterWoW_QuestEN[43591] = { title = "Leyline Feed: Ley Station Aethenar", description = "<This leyline appears to be damaged and needs repair.\n\nSeveral large chunks of the main column are missing and arcane energy is crackling in the gaps.\n\nThe elementals nearby seem to pick up debris and absorb it into their bodies as they move around. Maybe they have the missing pieces...>", objectives = "Collect 6 Leyline Feed Fragments and infuse the feed with ancient mana.", progress = "<The leyline feed crackles as wild energy escapes the gaps in the column.>", completion = "<As you insert the fragments back into the pillar the arcane energy begins repairing the cracks. You infuse the feed with ancient mana and the structure stirs to life.>" }
WordHunterWoW_QuestEN[43592] = { title = "Leyline Feed: Falanaar Arcway", description = "<The leyline feed appears to be intact and undamaged, but is not functioning. An infusion of Ancient Mana should be enough to render it operational again.>", objectives = "Infuse the leyline feed with Ancient Mana.", progress = "<The leyline feed pulses softly.>", completion = "<As you imbue the feed with the mana the structure stirs to life. Your skin tingles as the surrounding air becomes charged with arcane power.>" }
WordHunterWoW_QuestEN[43593] = { title = "Leyline Feed: Falanaar Depths", description = "<The leyline feed appears to be intact and undamaged, but is not functioning. An infusion of Ancient Mana should be enough to render it operational again.>", objectives = "Infuse the leyline feed with Ancient Mana.", progress = "<The leyline feed pulses softly.>", completion = "<As you imbue the feed with the mana the structure stirs to life. Your skin tingles as the surrounding air becomes charged with arcane power.>" }
WordHunterWoW_QuestEN[43594] = { title = "Leyline Feed: Halls of the Eclipse", description = "<The leyline feed appears to be intact and undamaged, but is not functioning. An infusion of Ancient Mana should be enough to render it operational again.>", objectives = "Infuse the leyline feed with Ancient Mana.", progress = "<The leyline feed pulses softly.>", completion = "<As you imbue the feed with the mana the structure stirs to life. Your skin tingles as the surrounding air becomes charged with arcane power.>" }
WordHunterWoW_QuestEN[43595] = { title = "To Honor the Fallen", description = "Souls are not the only plunder Helya craves, and the kvaldir are ever eager to please.\n\nAmong their spoils are the venerable blades of fallen heroes who dared stand against Helya's minions. These blades belong in a place of honor, not among their wretched kind.\n\nReclaim the blades, for the honor of the Tideskorn!", objectives = "Collect 8 Ancient Tideskorn Blades from the kvaldir in Helmouth Shallows.", progress = "Do you have the blades?", completion = "I will see that these blades are returned where they belong.\n\nThe dead smile upon you, outsider." }
WordHunterWoW_QuestEN[43596] = { title = "Maw of Souls: Piercing the Mists", description = "In a time before memory, the Naglfar was the prize of Helya's fleet. It would seem that it has lived on to serve her once more.\n\nNow, the dread ship sails the sea of souls, and cuts through the mist unseen by the living. The kvaldir must have a way to summon her, and this is what you must seek.\n\nFind her berth and board the Naglfar. Put an end to the dread ship, and the souls of the Tideskorn may be redeemed.", objectives = "Defeat Helya in the Maw of Souls dungeon, then return to Havi in Valdisdall", progress = "Is it done?", completion = "With the dread ship sundered, the souls of the dead will know their judgement. \n\nOdyn will have his champions, and the Tideskorn will have their honor." }
