WordHunterWoW_QuestEN[43604] = { title = "Maw of Souls: Ymiron's Broken Blade", description = "You hold King Ymiron's blade and realize what a fierce combatant he would make, were he to fight on your side.\n\nPerhaps Odyn could be persuaded to force the vrykul King's spirit to fight alongside your army.", objectives = "Return to Skyhold and convince Odyn to raise King Ymiron.", completion = "Very well then.  Let it be done!" }
