WordHunterWoW_QuestEN[43697] = { title = "Warriors of Light", description = "We have gathered to celebrate our victory over the Burning Legion this day. Highlord, please join us.", objectives = "Listen as you are honored by the Order of the Silver Hand.", progress = "We rejoice in our triumph!", completion = "Thank you for leading us to victory. All hail, Highlord <name>!" }
WordHunterWoW_QuestEN[43698] = { title = "Lumenstone", description = "To prepare for the battle ahead, we will need armor and weapons.\n\nWe have learned of lumenstone, a rare metal that can negate magic... even fel magic.\n\nIt is found in small quantities all over the Broken Isles, and many of the native races use it in their own metalcrafting.\n\nWe should send our champions to target enemies around the Broken Isles - there should be plenty of lumenstone to be found in their stockpiles.", objectives = "Collect 50 Lumenstone by sending champions on \"Lumenstone\" missions.", progress = "Have you acquired any lumenstone?", completion = "There's enough lumenstone here to craft armor and weapons for an army. Thank you, Highlord." }
WordHunterWoW_QuestEN[43699] = { title = "Defenders of the World", description = "Requests are pouring in from across the Broken Isles for our aid, Highlord.\n\nI know that we are working to aid the priests at Netherlight Temple, but there are many others who need our help.\n\nWe cannot turn our backs on those who need our aid.", objectives = "Complete 10 World Quests.", completion = "Thank you, Highlord. Too many dangers abound in these dark times. With heroes like you out there, we are all a little bit safer." }
WordHunterWoW_QuestEN[43700] = { title = "A Light in the Darkness", description = "Highlord, thank goodness you've arrived! The invasion of Netherlight Temple has begun.\n\nOur forces are already waiting on the other side of the portal.\n\nJoin them, and we will close the trap around Lord Balnazzar.", objectives = "Go to Netherlight Temple using the priest's portal in Dalaran, then defend Netherlight Temple and slay Lord Balnazzar.", progress = "The priests have always been our allies and friends. Now, we stand united against a common cause.", completion = "Victory is ours, Highlord." }
WordHunterWoW_QuestEN[43701] = { title = "Champion: Lothraxion", description = "", objectives = "I am sure you have many questions, Highlord <name>. It was fate that our paths crossed that day on Niskara.\n\nI serve High Exarch Turalyon and Lady Alleria Windrunner. When the Legion turned its armies toward Azeroth, I was sent here to help protect it.\n\nHow I got to Niskara is a tale for another time, but had it not been for you, I would still be Balnazzar's prisoner.\n\nNow, I can fulfill my original mission. Let me fight for you. Together, we will drive back the Burning Legion!" }
WordHunterWoW_QuestEN[43702] = { title = "Softening the Target", description = "The Archdruid's end draws near. His memory will live on in the hearts of all who knew him.\n\nElothir's desperate efforts revealed that Malfurion is being held in Shala'nir, amidst the roots of Shaladrassil.\n\nMy love. So near, yet so far....\n\nShala'nir is infested with Nightmare creatures. To rush in would be suicide.\n\nI subdued one of Xavius' creatures. Use it against him, {name} and clear us a path.", objectives = "Slay 50 Nightmare Creatures in Shala'nir riding the Subdued Nightwing.", progress = "Have you managed to thin their numbers?", completion = "This place remains deadly, but we can now press forward." }
WordHunterWoW_QuestEN[43703] = { title = "Hub Mana Tree Tracking - Stage 01", description = "", objectives = "" }
WordHunterWoW_QuestEN[43704] = { title = "Hub Mana Tree Tracking - Stage 02", description = "", objectives = "" }
WordHunterWoW_QuestEN[43705] = { title = "Nobundo's Last Stand", description = "The Exodar shook from the force of the Legion's arrival. Before we could react, demons were running rampant through the halls, slaughtering everything in their path. If it were not for the Prophet, we would have all perished in the initial assault.\n\nI was charged with evacuating the Crystal Hall, which is when my Broken and I were separated from the main force.\n\nWe fell back into the collapsed hall to make our last stand.\n\nWith your aid, we may survive this invasion.", objectives = "Defend Farseer Nobundo from the Legion Assault.", progress = "The Legion must fall!", completion = "You have my thanks, and the gratitude of the Broken, hero. Many would have considered us an acceptable loss, yet you have shown us great compassion and kindness. An act that I - we - will not soon forget.\n\nNow we will return to the Vault of Lights and assist Velen as best we can." }
