WordHunterWoW_QuestEN[43724] = { title = "Champion: Master Mathias Shaw", description = "", objectives = "Shall we form an alliance, you and I? Of course, I dare not officially become one of the Uncrowned, let alone the Council of Shadows.\n\nI am the leader of SI:7 after all.\n\nBut, when you need my assistance or guidance, you need but ask. I will be there. We will work together through back channels to ensure that the Burning Legion is destroyed." }
