WordHunterWoW_QuestEN[43797] = { title = "Aiding the Conclave", description = "The priests of the Conclave are formidable allies. With our combined strength, we may just have a chance to slay the dreadlord, forever.\n\nLet Alonsus Faol know that we will be by your side and ready to fight when you need us.", objectives = "Return to Alonsus Faol within Netherlight Temple.", completion = "With the paladins on our side, united under the Light, the prophecy is fulfilled.\n\nWe must now prepare. Balnazzar will attack, and we need to be ready." }
