WordHunterWoW_QuestEN[43806] = { title = "The Battle for Broken Shore", description = "The third fleet has shipped out ahead of us, {name}. This gryphon will bring you to them.\n\nGood luck out there. It's clear the Legion isn't going to make this easy, but let's hope King Varian has matters well in hand.", objectives = "Rendezvous with the third fleet.", completion = "Ah, <name>, you're up! I'm relieved you made it out of that bloodbath alive. We lost so many good women and men down there...\n\n\n\nDamn the Horde for serving us up to the Legion!" }
