WordHunterWoW_QuestEN[43808] = { title = "Moon Guard Teleporter Online!", description = "<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>", objectives = "Infuse the Telemancy Beacon with Ancient Mana.", progress = "<The beacon is cold and dark.>", completion = "<The beacon glows as you infuse it with Ancient Mana.>" }
WordHunterWoW_QuestEN[43809] = { title = "Tel'anor'eporter Online!", description = "<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>", objectives = "Infuse the Telemancy Beacon with Ancient Mana.", progress = "<The beacon is cold and dark.>", completion = "<The beacon glows as you infuse it with Ancient Mana.>" }
WordHunterWoW_QuestEN[43810] = { title = "Down to Business", description = "First things first, {name}: we must set up our camp.\n\nWe do not have the time or resources for a prolonged siege. It is not like we can starve them out. No, we must be swift and sure as an arrow, piercing their heart in one strike.\n\nThey are drawing up their battle lines within the city, but could attack us while we are setting up our defenses.\n\nVenture forth and show them what the kaldorei have learned from thousands of years of war. Discover their weaknesses so that we may exploit them.", objectives = "Enter the Grand Promenade and slay 15 defenders.", completion = "Any regret I had for these people vanished when they went under that shield." }
WordHunterWoW_QuestEN[43811] = { title = "Lunastre Estate Teleporter Online!", description = "<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>", objectives = "Infuse the Telemancy Beacon with Ancient Mana.", progress = "<The beacon is cold and dark.>", completion = "<The beacon glows as you infuse it with Ancient Mana.>" }
WordHunterWoW_QuestEN[43812] = { title = "Down to Business", description = "Time to get to business, {name}. We cannot afford to tarry.\n\nWhile we are not setting up for a prolonged engagement, we must still have a war camp of some sorts. I do not expect the Nightborne to stay patiently in their city while we plant stakes.\n\nThey are starting to build their defenses. Go in there and see what we are up against. You will strike them from within while we finalize our preparations.", objectives = "Enter the Grand Promenade and slay 15 defenders.", completion = "Excellent. We will be able to defend our borders for now." }
WordHunterWoW_QuestEN[43813] = { title = "Sanctum of Order Teleporter Online!", description = "<The telemancy beacon is deactivated, but intact. Some Ancient Mana should get it back up and running.>", objectives = "Infuse the Telemancy Beacon with Ancient Mana.", progress = "<The beacon is cold and dark.>", completion = "<The beacon glows as you infuse it with Ancient Mana.>" }
