WordHunterWoW_QuestEN[43816] = { title = "Hidden History", description = "I will need more research material if I'm to keep improving on our current records.\n\nIf I am to get started, I need a series of ancient tomes to begin my research. They may be hard to procure. I'll give you my notes to help you find them.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use Illiana Dreadmoore's notes to locate and recover the 4 ancient tomes she needs to begin research on your artifact." }
WordHunterWoW_QuestEN[43817] = { title = "Hidden History", description = "It may sound strange, but in order to do more research I will need, uh, more research material.\n\nIf I am to get started, I need a series of ancient tomes to begin my research. They may be hard to procure. I'll give you my notes to help you find them.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use Vehu's notes to locate and recover the 4 ancient tomes he needs to begin research on your artifact." }
WordHunterWoW_QuestEN[43818] = { title = "Hidden History", description = "I will need to increase our overall knowledge levels before I can research the artifact further.\n\nBefore I can get started, I need a series of ancient tomes to begin my research. They may be hard to procure. I'll give you my notes to help you find them.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use Celadine's notes to locate and recover the 4 ancient tomes she needs to begin research on your artifact." }
WordHunterWoW_QuestEN[43819] = { title = "Hidden History", description = "You have a weapon both ancient and powerful. And yet, we barely understand it.\n\nIf we truly want to unlock all of its potential, we need to learn more about it. I can help with that.\n\nBefore I can get started though, I need a series of ancient tomes. They may be hard to procure. I asked one of the scouts to seek them out, here are her notes.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the scouting notes to locate and recover the 4 ancient tomes Holt needs to begin research on your artifact." }
WordHunterWoW_QuestEN[43820] = { title = "Hidden History", description = "We definitely have plans to improve our research methods. \n\nBefore I can get started though, I need a series of ancient tomes to begin my research. They may be hard to procure. I had one of the initiates attempt to find them. Here are her notes.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the scouting notes to locate and recover the 4 ancient tomes Lorewalker Cho needs to begin research on your artifact." }
WordHunterWoW_QuestEN[43821] = { title = "Hidden History", description = "I have some ideas on how we can improve our research methods.\n\nBefore I can get started though, I need a series of ancient tomes to begin my research. They may be hard to procure. I put one of the researchers on digging up where they might be. Here are her notes.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use Sister Elda's notes to locate and recover the 4 ancient tomes she needs to begin research on your artifact." }
WordHunterWoW_QuestEN[43822] = { title = "Hidden History", description = "More research? Absolutely!\n\nBefore I can get started though, I need a series of ancient tomes to begin my research. They may be hard to procure. I'll give you my notes to help you find them.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use Juvess' notes to locate and recover the 4 ancient tomes she needs to begin research on your artifact." }
WordHunterWoW_QuestEN[43823] = { title = "Hidden History", description = "I think I can help you, I mean all of us, out.\n\nBefore I can get started though, I need some books. Some important ones. They may be hard to pinch. I'll give you my notes to help you find them.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use Fillius' notes to locate and recover the 4 ancient tomes he needs to begin research on your artifact." }
WordHunterWoW_QuestEN[43824] = { title = "Hidden History", description = "I know of a few books that will give me the right place to start. They may be hard to get your hands on, but they'll be worth it. I'll give you my notes to help you find them.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use Gorma's notes to locate and recover the 4 ancient tomes she needs to begin research on your artifact." }
WordHunterWoW_QuestEN[43825] = { title = "Hidden History", description = "Before I can get started though, I need a series of ancient tomes to begin my research. They may be hard to procure. I'll give you my notes to help you find them.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use Mile's notes to locate and recover the 4 ancient tomes he needs to begin research on your artifact." }
WordHunterWoW_QuestEN[43826] = { title = "Hidden History", description = "You wield ancient steel, strengthened by magics we barely understand.\n\nIf you truly want to unlock the potential of your weapons, you need to know more of how they were forged, and of the battles they've fought in. I can help with this.\n\nYour races use books to store their histories, and I will need some of these to piece together the legend of your steel. I asked one of your followers to look into their locations for me. Here are her notes.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the scouting notes to locate and recover the 4 ancient tomes Fjornson needs to begin research on your artifact." }
