WordHunterWoW_QuestEN[43841] = { title = "Convincin' Old Yancey", description = "Avast ye! Th' time be long overdue that we get some more pirate blood into our ranks.\n\n<Crackers gives a sudden squawk in agreement.>\n\nAnd I know just th' man t' do it.\n\nI'm talkin' about good old Yancey Grillsen, o' course. He's an old salt down Stranglethorn way.\n\nSend some o' your land lovin' scallywags off t' round him up.", objectives = "Use the Scouting Map and complete the mission, \"Convincin' Old Yancey\".", completion = "Arrr! Now that be what I like t' hear.\n\nWhat do you think, Crackers... will a bunch o' freebooters class up this crow's nest or scuttle th' ship? I say it's a fair toss o' th' bones." }
