WordHunterWoW_QuestEN[43877] = { title = "Hitting the Books", description = "Any death knight worth their salt knows the weapon they wield as if they were born with it.  But you now carry a weapon older than any in this hall.\n\nIf we truly want to unlock all of its potential, we need to learn more about it. It will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.\n\nWe should prioritize some of the order's resources towards this research. I promise you it will be worth every minute.", objectives = "Start a Research Work Order.", completion = "Excellent. I'll get back to you with the results as soon as I can." }
WordHunterWoW_QuestEN[43878] = { title = "Hitting the Books", description = "A demon hunter is nothing without blades with which to cut flesh. Yet those you wield are older than even you... and have power we don't understand yet.\n\nIf you truly want to unlock all of their potential, we need to learn more about them. It will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.\n\nWe should prioritize some of the order's resources towards this research. I promise you it will be worth every minute.", objectives = "Start a Research Work Order.", completion = "Excellent. I'll get back to you with the results as soon as I can." }
WordHunterWoW_QuestEN[43879] = { title = "Hitting the Books", description = "You have a weapon both ancient and powerful. And yet, we barely understand it. If we truly want to unlock all of its potential, we need to learn more about it. That's where I come in. It's my specialty.\n\nStill, it will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.\n\nWe should prioritize some of the order's resources towards this research. I promise you it will be worth every minute.", objectives = "Start a Research Work Order.", completion = "Excellent. I'll get back to you with the results as soon as I can." }
WordHunterWoW_QuestEN[43880] = { title = "Hitting the Books", description = "You have a weapon both ancient and powerful. And yet, we barely understand it. If we truly want to unlock all of its potential, we need to learn more about it. I can help with that.\n\nStill, it will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.\n\nWe should prioritize some of the order's resources towards this research. It will be worth every minute.", objectives = "Start a Research Work Order.", completion = "Excellent. I'll get back to you with the results as soon as I can." }
WordHunterWoW_QuestEN[43881] = { title = "Hitting the Books", description = "You have a weapon both ancient and powerful. And yet, we barely understand it. If we truly want to unlock all of its potential, we need to learn more about it. I am quite good at such things.\n\nStill, it will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.\n\nWe should prioritize some of the order's resources towards this research. It will be worth every minute.", objectives = "Start a Research Work Order.", completion = "Excellent. I'll get back to you with the results as soon as I can." }
WordHunterWoW_QuestEN[43882] = { title = "The Nighthold: Vaults", description = "The Nighthold will be a challenge to infiltrate and conquer. Even the catacombs and vaults are likely to be heavily guarded, but we must make our way in by any route possible.", objectives = "Kill Trilliax in The Nighthold.", progress = "How are you finding the challenges of the The Nighthold?", completion = "Were you able to overcome the The Nighthold?" }
WordHunterWoW_QuestEN[43883] = { title = "Hitting the Books", description = "You have a mighty weapon with a long history, one we barely understand. If we truly want to unlock all of its potential, we need to learn more about it. I can get workin' on that for ya.\n\nStill, it'll take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.\n\nWe should prioritize some of the order's resources towards this research. It will be worth every minute.", objectives = "Start a Research Work Order.", completion = "Excellent. I'll get back to you with the results as soon as I can." }
WordHunterWoW_QuestEN[43884] = { title = "Hitting the Books", description = "You have a weapon both ancient and powerful. And yet, we barely understand it. If we truly want to unlock all of its potential, we need to learn more about it. I can do this for you.\n\nStill, it will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.\n\nWe should prioritize some of the order's resources towards this research. It will be worth every minute.", objectives = "Start a Research Work Order.", completion = "Excellent. I'll get back to you with the results as soon as I can." }
WordHunterWoW_QuestEN[43885] = { title = "Hitting the Books", description = "Your weapons are undeniably powerful, but we know near nothing about'm.\n\nIf we want to unlock all of their potential, we need to dig up some dirt on how they work, what they've done... get to know them, ya know? That's where I come in. I dig up dirt all the time. I mean, not literally, but... you know what I mean.\n\nIt will take time and more eyes than just mine to sift through all this. We should prioritize some of the order's resources towards this research. It will be worth every minute.", objectives = "Start a Research Work Order.", progress = "I like books.", completion = "On it, boss. Will get back to you soon!" }
WordHunterWoW_QuestEN[43886] = { title = "Speaking to the Wind", description = "You have a weapon both ancient and powerful. We know stories of it, but little about its origins.\n\nIf we truly want to unlock all of its potential, we need to learn more about it. The winds can help us with this, but we need to know what to ask.\n\nIt will take more shaman than just myself to learn everything there is to know about this artifact of yours. We should prioritize some of the order's resources towards this research. It will be worth every minute.", objectives = "Start a Research Work Order.", completion = "Thank you. I'll get back to you with what I've learned soon." }
WordHunterWoW_QuestEN[43887] = { title = "Hitting the Books", description = "You have a weapon both ancient and powerful. And yet, we barely understand it. If we truly want to unlock all of its potential, we need to learn more about it. That is a thing that I can do for you.\n\nStill, it will take time and more eyes than just mine to sift through all this history, translate it, and turn it into something meaningful.\n\nWe should prioritize some of the order's resources towards this research. It will be worth every minute.", objectives = "Start a Research Work Order.", completion = "Very good. I'll get back to you with the results soon." }
WordHunterWoW_QuestEN[43888] = { title = "Hitting the Books", description = "You wield ancient steel, strengthened by magics we barely understand.\n\nIf you truly want to unlock the potential of your weapons, you need to know more of how they were forged, and of the battles they've fought in. I can help with this.\n\nAny resources that you can prioritize towards this research will be well worth it.", objectives = "Start a Research Work Order.", completion = "I will have results for you soon." }
