WordHunterWoW_QuestEN[43892] = { title = "Sealing Fate: Order Resources", description = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Your order will certainly not miss these extra resources, but I must ask: When does it end?  Will you ever stop risking others lives just to satisfy your greedy nature?\n\nYou can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", objectives = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Your order will certainly not miss these extra resources, but I must ask: When does it end?  Will you ever stop risking others lives just to satisfy your greedy nature?\n\nYou can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", progress = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Your order will certainly not miss these extra resources, but I must ask: When does it end?  Will you ever stop risking others lives just to satisfy your greedy nature?\n\nYou can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", completion = "Feeling safe, stranger?" }
WordHunterWoW_QuestEN[43893] = { title = "Sealing Fate: Stashed Order Resources", description = "Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be easier for you?  I leave the choice up to you.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", objectives = "Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be easier for you?  I leave the choice up to you.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", progress = "Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be easier for you?  I leave the choice up to you.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", completion = "Feeling safe, stranger?" }
WordHunterWoW_QuestEN[43894] = { title = "Sealing Fate: Extraneous Order Resources", description = "Four times the cost of the first for only one seal.  Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", objectives = "Four times the cost of the first for only one seal.  Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", progress = "Four times the cost of the first for only one seal.  Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", completion = "Feeling safe, stranger?" }
WordHunterWoW_QuestEN[43895] = { title = "Sealing Fate: Gold", description = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Gold is indeed treasure, but additional treasure for gold?  That is the offer I present.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", objectives = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Gold is indeed treasure, but additional treasure for gold?  That is the offer I present.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", progress = "These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Gold is indeed treasure, but additional treasure for gold?  That is the offer I present.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", completion = "A simple exchange with complex results.  That's the art of doing business." }
WordHunterWoW_QuestEN[43896] = { title = "Sealing Fate: Piles of Gold", description = "Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be easier for you?  I leave the choice up to you.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", objectives = "Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be easier for you?  I leave the choice up to you.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", progress = "Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be easier for you?  I leave the choice up to you.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", completion = "A simple exchange with complex results.  That's the art of doing business." }
WordHunterWoW_QuestEN[43897] = { title = "Sealing Fate: Immense Fortune of Gold", description = "Four times the cost of the first, but for only one seal.  Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", objectives = "Four times the cost of the first, but for only one seal.  Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", progress = "Four times the cost of the first, but for only one seal.  Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I will have others.", completion = "A simple exchange with complex results.  That's the art of doing business." }
WordHunterWoW_QuestEN[43898] = { title = "Preparing to Move", description = "Thanks to your tireless efforts the Heart of Zin-Azshari is ready to withstand the full power of the Legion.\n\nThe final destination in our journey has stood defiantly in front of us from the moment we began - the Nighthold, now home to none other than Gul'dan himself.\n\nBefore we move on the hold, we should reunite with the Moon Guard in Shal'Aran - we still have need of their skills, and I would wager that they have unfinished business with their former brothers and sisters.", objectives = "Meet Archmage Kalec in Shal'Aran.", completion = "We've found a back entrance into the Nighthold that should provide some relief from the armies at the main gate.\n\n'Some' being key." }
WordHunterWoW_QuestEN[43899] = { title = "Steeds of the Damned", description = "Salanar the Horseman has arrived at Ebon Hold from the Realm of Shadows. He alone has the knowledge and power to conjure the steeds of the Four Horsemen.\n\nSalanar has given us the first list of necessary components to create the steeds. I have organized a number of missions to obtain these items.\n\nUse the mission table to assign your chosen champions to the task.", objectives = "Complete 5 \"Fallen Steeds\" missions.", completion = "Excellent work, Deathlord. The missions for the Steeds of the Damned were successful. Salanar the Horseman now has the first set of necessary components for conjuring the steeds." }
