WordHunterWoW_QuestEN[43902] = { title = "The Emerald Nightmare: Fall of Cenarius", description = "While we know that the Nightmare bends the boundary between reality and dream, there is no doubt of the threat upon us. Our own allies have fallen into darkness.", objectives = "Defeat Cenarius in the Emerald Nightmare.", progress = "How are you finding the challenges of the Emerald Nightmare?", completion = "Were you able to overcome the Emerald Nightmare?" }
WordHunterWoW_QuestEN[43903] = { title = "The Emerald Nightmare: Xavius", description = "The time has come to tackle the source of the Nightmare, and restore balance to the Emerald Dream. Battle into the heart of the Nightmare, and face the Nightmare Lord Xavius.", objectives = "Defeat Xavius in the Emerald Nightmare.", progress = "How are you finding the challenges of the Emerald Nightmare?", completion = "Were you able to overcome the Emerald Nightmare?" }
