WordHunterWoW_QuestEN[43910] = { title = "The Nighthold: High Botanist Tel'arn", description = "The Nightborne are adept in more than one kind of magic, and we will likely face formidable foes inside the walls of the Nighthold. Their strongest mages and warriors must fall before we can hope to face Gul'dan.", objectives = "Kill High Botanist Tel'arn in The Nighthold.", progress = "How are you finding the challenges of the The Nighthold?", completion = "Were you able to overcome the The Nighthold?" }
WordHunterWoW_QuestEN[43911] = { title = "The Nighthold: Elisande", description = "Long ago, Grand Magistrix Elisande opposed the Legion and defied Queen Azshara herself. Passing millennia have changed Elisande's mind, and turned her into an ally of the demons. The time has come to face her.", objectives = "Kill Elisande in The Nighthold.", progress = "How are you finding the challenges of the The Nighthold?", completion = "Were you able to overcome the The Nighthold?" }
WordHunterWoW_QuestEN[43912] = { title = "The Nighthold: Gul'dan", description = "Gul'dan believed that the Legion was the destiny of the orcs, and has not paused in his brutal pursuit. Now, at last, the time has come to end his demonic crusade, and dispense justice for all.", objectives = "Kill Gul'dan in The Nighthold.", progress = "How are you finding the challenges of the The Nighthold?", completion = "Were you able to overcome the The Nighthold?" }
