WordHunterWoW_QuestEN[43926] = { title = "Legion: The Legion Returns", description = "Warriors of da Horde! Break out ya axes and sharpen ya spears. Da Burning Legion has returned ta our world!\n\nWe be shipping outta Bladefist Bay right away. With da full fury of da Horde, we gonna smash der line so hard dat Sargeras is gonna feel it in da Nether!\n\nGet to da ships. We got demons ta slay!", objectives = "Check in with Holgar Stormaxe at the Dranosh'ar Blockade.\n\nProvided item:", completion = "The ships are leaving from the dock in Bladefist Bay.\n\nBefore you leave, prepare yourself. I have the feeling that this fight won't be an easy one." }
WordHunterWoW_QuestEN[43928] = { title = "Aggregates of Anguish", description = "Our preparations for conjuring the Steeds of the Damned are nearly complete.\n\nSalanar the Horseman has given us a list of the remaining components. The ritual of conjuring requires five unholy essences known as the Aggregates of Anguish.\n\nI have taken it upon myself to organize the necessary missions to obtain these components.\n\nUse the mission table to assign your chosen champions to the task.", objectives = "Complete 5 \"Unholy Attainment\" missions.", completion = "With the Aggregates of Anguish procured, our work is nearly complete. Soon, the Steeds of the Damned will rise... and the Burning Legion will fall!" }
WordHunterWoW_QuestEN[43929] = { title = "Vantus Mastery", description = "", objectives = "Greetings, <name>.\n\nIt is my understanding that you have been one of the foremost scribes responsible for equipping our forces with Vantus runes. Do not think that your efforts as an artisan have gone unnoticed.\n\nWe noticed.\n\nI would like to present you with this technique. Now go, and use it to help us win this war." }
WordHunterWoW_QuestEN[43930] = { title = "Fiends of Tel'anor", description = "", objectives = "" }
WordHunterWoW_QuestEN[43932] = { title = "Forces of Oppression", description = "", objectives = "" }
WordHunterWoW_QuestEN[43933] = { title = "Champion: Delas Moonfang", description = "", objectives = "Highlord, I am proud to begin the first steps of this new journey.\n\nThank you for taking me under your wing. I vow to follow the guiding principles - to act honorably, to uphold what is righteous, to fight against injustice, and to celebrate with my new brothers and sisters of the Silver Hand.\n\nUnder the Light, we stand as one!" }
WordHunterWoW_QuestEN[43934] = { title = "A New Path", description = "Highlord {name}, if I could have a moment of your time?\n\nLong have I followed the path of the Light, and for many years I studied under the Priestesses of the Moon. Yet, I have always felt my education incomplete, and a yearning to know more.\n\nWhen I walked into these halls, I finally felt a spark of what was missing. I believe that a new path lies before me.\n\nI wish to become a paladin of the Silver Hand. Will you allow me to join you?", objectives = "Speak to Delas Moonfang.", progress = "What do you think?", completion = "Thank you, Highlord." }
WordHunterWoW_QuestEN[43935] = { title = "A Second Legend", description = "Perhaps it's time to consider improving your flexibility when it comes to powerful artifacts. There are still others that I think are worth pursuing if you are interested.\n\nLet me show you what your options are and you can choose one.", objectives = "Choose a second artifact to pursue.", completion = "Excellent. You can begin as soon as you are ready." }
WordHunterWoW_QuestEN[43937] = { title = "Seeking Refuge", description = "The Nightfallen in Suramar were once a part of the Nightborne, but have been exiled by their former brethren and cut off from the Nightwell.\n\nI believe they could be valuable allies in our quest if you can turn them to our side. I know only that they have gone into hiding somewhere in Suramar.\n\nIf you can convince the Nightfallen to aid us, they may be able to offer the Moon Guard and us both refuge right under the Legion's nose.", objectives = "Complete the \"Nightfall\" storyline in Suramar, then meet Archmage Kalec in Shal'Aran." }
WordHunterWoW_QuestEN[43938] = { title = "Focusing Our Efforts", description = "The Nightfallen in Suramar were once a part of the Nightborne, but have been exiled by their former brethren and cut off from the Nightwell.\n\nI believe they could be valuable allies in our quest if you can turn them to our side. I know only that they have gone into hiding somewhere in Suramar.\n\nAfterward, seek out the Moon Guard in the northern reaches of Suramar. They, too, could be valuable allies in our cause... if they still oppose the Legion as they once did many years ago.", objectives = "Complete the \"Nightfall\" and \"Moon Guard Stronghold\" storylines in Suramar, then meet Archmage Kalec in Shal'Aran.", completion = "Let us speak with Thalrenus and discuss our plan of action." }
WordHunterWoW_QuestEN[43939] = { title = "Shadow Chosen", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[43940] = { title = "Holy Chosen", description = "", objectives = "You will receive:" }
