WordHunterWoW_QuestEN[43942] = { title = "Timeworn Artifact", description = "<You've found a strange looking naga artifact on the fallen corpse.\nYou saw King Mrgl Mrgl as you were walking around Timeworn Strand. Maybe he knows what to do with it?>", objectives = "Take the Timeworn Artifact to King Mrgl Mrgl nearby.\n\nProvided item:", completion = "Just what I've been looking for! <King Mrgl Mrgl studies the artifact> Ah! Yes. But there must be more of these Timeworn Artifacts still on the shore. Any more you can bring back would be greatly appreciated!" }
WordHunterWoW_QuestEN[43943] = { title = "Withered Army Training", description = "", objectives = "" }
WordHunterWoW_QuestEN[43945] = { title = "Expanding Your Horizons", description = "You are a fast study, {class}t {name}. The elements speak through you - it is rare to have such a connection to the world.\n\nA true shaman must walk many paths. For every role, one must have the right tools at hand. Only the most powerful weapons can lead us to victory against the Legion. Perhaps it is time to seek out another?\n\nSpeak with me and let us discuss your options.", objectives = "Speak with Aggra to choose a second artifact to pursue.", completion = "Very well. Your allies have gathered here on the precipice - they will know how best to proceed.\n\nMay the winds be ever in your favor, Farseer." }
