WordHunterWoW_QuestEN[43949] = { title = "More Weapons of Legend", description = "It is wise to carry more than one weapon to war. Sometimes one will be better suited than another. You should choose another weapon of legend to carry with you, especially against foes so deadly.\n\nWhat say you?", objectives = "Choose a second artifact to pursue.", completion = "A powerful weapon for a powerful champion of the Halls. Let us begin." }
