WordHunterWoW_QuestEN[43962] = { title = "Blades of Destiny", description = "I'm glad that weapon you've been carrying around has proven useful. Our ally, the Lich King, has offered to provide you with a lead on another weapon should the one you already have somehow be lacking.\n\nConsider the options carefully and let me know which you would like to seek out.", objectives = "Choose a second artifact to pursue.", completion = "Very well." }
