WordHunterWoW_QuestEN[43973] = { title = "Two Paths, Two Weapons", description = "We've searched through our scrolls and have found new leads on a couple of powerful weapons. They may prove beneficial in our efforts.\n\nHere, let me show you what I've found. If any of these interest you then simply let me know.", objectives = "Choose a second artifact to pursue.", completion = "A wise choice." }
