WordHunterWoW_QuestEN[43975] = { title = "Recruiting Shieldmaidens", description = "The powerful val'kyr Savyn Valorborn has arrived to aid us in bolstering our numbers. She ushers some of the most valorous vrykul shieldmaidens into the Halls of Valor.\n\nSpeak to her and recruit powerful troops to add to our roster.", objectives = "Speak to Savyn Valorborn.", completion = "I will rally the worthy in Odyn's name." }
