WordHunterWoW_QuestEN[43991] = { title = "The Protectors", description = "To fully unlock the powers of the Idol, we will need four manifestations of the wilds - an essence of ferocity, essence of regrowth, essence of balance, and essence of tenacity.\n\nTo find these essences, we must consult the protectors of the forest.\n\nGo to the Emerald Dreamway and call upon the powers of the ancient druidic stones. The protectors will only show themselves to those who can prove their connection to the wilds.", objectives = "Use your druidic powers to commune with protectors at the Feral Stone, the Guardian Stone, the Restoration Stone, and the Balance Stone.", completion = "Did you sense the protectors of the wilds? Their presence is ever with us." }
