WordHunterWoW_QuestEN[44004] = { title = "Bringer of the Light", description = "Turalyon lives! For ages I had thought that my old friend had perished on some desolate Legion world. But to know that he yet lives and is in danger is too much to bear.\n\nWe must hurry, {name}. We must uncover the object's sacred purpose.\n\nThe prophet of whom Turalyon spoke of is undoubtedly the leader of the draenei, Velen. Take the object and journey to the Exodar. It is there that you will find Prophet Velen.\n\nI will open a portal for you now. Take my beacon and use it when you are ready to return.", objectives = "Discover the purpose of the Mysterious Lightbound Object.", progress = "Have you discovered anything about the object?", completion = "Kil'jaeden took the child from Velen, let Velen believe that the boy had been killed, then raised the child as an agent of the Burning Legion with the express purpose of murdering his own father? That bastard waited 13,000 years to exact vengeance upon Velen for defying Sargeras and the Legion? The Deceiver indeed...\n\nFor Velen to have to experience such tragedy after what he and his people have already been through is heartbreaking. Such a thing would test anyone's faith." }
WordHunterWoW_QuestEN[44005] = { title = "Tracking Quest: Reaction to Warrior Artifacts", description = "", objectives = "" }
WordHunterWoW_QuestEN[44006] = { title = "Your Fullest Potential", description = "I see that you walk many paths, as a true shaman should.\n\nTwo mighty artifacts are already in your possession. To seek a third would not be greed: it would be the fulfillment of your destiny, the completion of a circle.\n\nSpeak with me, and together we will unlock your fullest potential.", objectives = "Speak with Aggra to choose a third artifact to pursue.", progress = "Where are the spirits guiding you, Farseer?", completion = "The path ahead is clear. Your allies await you on this ledge. May the spirits walk with you, Farseer!" }
WordHunterWoW_QuestEN[44008] = { title = "DO NOT LOCALIZE - TEMP PRE-REQ", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[44009] = { title = "A Falling Star", description = "{class}t {name}, thank you for coming. I have a matter of some urgency that requires your unique talents.\n\nThe Order of the Silver Hand have reported that an extraordinarily luminescent object has emerged from the Felstorm and is currently falling towards the coast of Suramar. What I find most curious about this occurrence is that the object was reported as having \"cut a swath\" through the Felstorm itself.\n\nWill you investigate? There is a gryphon awaiting your arrival at Krasus' Landing.", objectives = "Find the Mysterious Lightbound Object.", progress = "Show me what you've found.", completion = "Most curious indeed! This is no object of the Legion's making. Let me have a closer look." }
