WordHunterWoW_QuestEN[44034] = { title = "Another Worthy Blade", description = "We still have plans prepared to obtain other weapons of incredible power - tools that you may find useful to have on hand as you continue your work.\n\nI would be happy to go over the remaining options with you so that you may make an informed decision.", objectives = "Choose a second artifact to pursue.", completion = "Yes, I think that will do rather nicely as well.\n\nGood choice." }
