WordHunterWoW_QuestEN[44051] = { title = "Wasted Potential", description = "You have done well for us here, but it is time for you to return to Thalyssra.\n\nThere is a teleporter pad nearby that has gone unused in recent years. See if you can reroute it and return to her that way.\n\nOh, and before you go:\n\n<Vanthir hands you a wrapped bottle of Arcwine.>\n\nTake this to her, with my thanks for sending you. Let her know that your efforts helped replenish our Arcwine supplies and reunited a mother and child.\n\nWe are grateful beyond measure. Farewell for now.", objectives = "Activate the teleporter pad and bring Vanthir's gift to Thalyssra.", completion = "I heard rumors that you intend to leave the City... that there is another place for the Nightborne where we are not beholden to Elisande's insanity.\n\nI wish to go with you.\n\nI can offer my harp and my hands, as they are not wanted here.\n\nSay the word and I will go with you through the teleporter and share my music with whomever awaits me on the other side." }
WordHunterWoW_QuestEN[44052] = { title = "And They Will Tremble", description = "There will be consequences for what has transpired this day.\n\nFor now, you should return to Thalyssra. Tell her that we have avenged Margaux and that the Dusk Lily has announced itself to all of Suramar.\n\nThere will be many more deaths before this is over, rest assured, but this is a death that will teach others like Durant to tread more carefully in the future.", objectives = "Return to Thalyssra", completion = "It is a relief, if a small one. You have done well - rest for now." }
WordHunterWoW_QuestEN[44053] = { title = "Friends With Benefits", description = "The Lunastre Attendant, silent as ever, offers you a wax-sealed scroll.\n\nIt reads:\n\"Dearest {name},\n\nI asked my attendant to catch you, should things go in my favor.\n\nThe role of Advisor will keep me away from the estate for some time and I settled on a gift for Thalyssra.\n\nI have sent a detachment of attendants to Shal'Aran with some comfort items. Treat them well- they need someone to wait on and I could think of none better!\n\nGive the others my thanks, and my love,\nAdvisor Ly'leth Lunastre\"", objectives = "Return to Thalyssra.", completion = "She certainly is a worthy companion." }
WordHunterWoW_QuestEN[44054] = { title = "Demonicide", description = "", objectives = "" }
WordHunterWoW_QuestEN[44055] = { title = "They Have A Pitlord", description = "The Feltotem are not the first to embrace the temptations of the Burning Legion. And they will not be the last.\n\nBut in their arrogance, they have conjured a pit lord.\n\nWill you join us in battle against this beast? The power of your artifact and skill could prove invaluable against such a creature.", objectives = "Defeat Kuglaroth.", completion = "The other demons we will contend with in time. But that pit lord, it was a creature of great evil and beyond our devices to defeat on our own. Your skills were appreciated." }
WordHunterWoW_QuestEN[44057] = { title = "A \"Noble\" Event", description = "The invitation appears to be for an exclusive fox hunt. They plan to hunt Volpin, a rare, elusive fox somewhere in the Broken Isles.  Perhaps we can take advantage of this?\n\nWe need to gather more information about this hunt, but we should do so without alerting the Nightborne to your plans. Your champions can act in your stead and further  investigate where the hunt will be.", objectives = "Send champions on missions to investigate the hunt.", progress = "Have your champions discovered anything about the fox hunt?", completion = "Yes, its all here, the location of the hunt for Volpin. \n\nI'm sure there are better uses for a wonderful creature such as he than a pelt on some Noble's shoulders, don't you agree?" }
WordHunterWoW_QuestEN[44058] = { title = "Volpin the Elusive", description = "According to the map, the fox hunt will start at the Feathermane Hunting Grounds in Suramar. If the Nightborne succeed, they will kill Volpin, a fox that is the last of his kind in the Broken Isles.\n\nTravel to the Hunting Grounds, and interrupt the hunt.", objectives = "Interrupt the fox hunt." }
WordHunterWoW_QuestEN[44059] = { title = "Legion Attacks", description = "", objectives = "" }
