WordHunterWoW_QuestEN[44063] = { title = "Bolstering Your Arsenal", description = "Highlord, there are still weapons that you might obtain to help you defeat the Legion. We have kept a close eye on them during your time on the Broken Isles.\n\nI would be happy to review them with you if you wish.", objectives = "Choose a second artifact to pursue.", completion = "Excellent. There's no time to waste." }
