WordHunterWoW_QuestEN[44074] = { title = "Neltharion's Lair: Essence of Tenacity", description = "Greetings, Archdruid. I hear that you seek the essence of tenacity.\n\nThere is none more unyielding and unbreakable than a creature of stone.\n\nIn Neltharion's Lair is a monster known as Rokmora. Slay him, and draw from him the essence that you need.", objectives = "Collect 1 Essence of Tenacity from Rokmora in Neltharion's Lair, then slay Dar'grul the Underking.", progress = "Stand firm, <class>.", completion = "Thank you, Archdruid." }
WordHunterWoW_QuestEN[44075] = { title = "Halls of Valor: Essence of Ferocity", description = "To find the essence of ferocity, you must seek a creature who has slain thousands, and is revered by even the gods.\n\nI speak of none other than the wolf, Fenryr, whom you can find hunting in the eternal forests of the Halls of Valor.", objectives = "Collect 1 Essence of Ferocity from Fenryr in the Halls of Valor, then prove your worth to Odyn.", progress = "It takes a ferocious beast to take down another ferocious beast.", completion = "Excellent, Arch <class>." }
WordHunterWoW_QuestEN[44076] = { title = "Darkheart Thicket: Essence of Regrowth", description = "My child, I can think of only one place to capture the essence of regrowth.\n\nDeep within Darkheart Thicket is Oakheart, a loyal ancient defender of the grove. He has recently fallen to the Nightmare's corruption, but deep within his heart, he still fights.\n\nGather the essence of this great tree, so that his everliving soul may be used to fuel new life.", objectives = "Collect 1 Essence of Regrowth from Oakheart in Darkheart Thicket, then defeat the Shade of Xavius.", progress = "My heart aches for those fallen to the Nightmare.", completion = "I am sad to hear of Oakheart's demise, but his soul will live on." }
WordHunterWoW_QuestEN[44077] = { title = "Eye of Azshara: Essence of Balance", description = "Within the Eye of Azshara in Azsuna, a powerful being known as the Wrath of Azshara grows in strength. It is a blasphemy of nature - an infusion of stolen arcane power, and cannot be allowed to exist.\n\nSlay it. In its aftermath, you may find the essence of balance that you seek.", objectives = "Collect 1 Essence of Balance from the Wrath of Azshara.", progress = "We follow Elune's path.", completion = "Wonderful. This is exactly what we need." }
WordHunterWoW_QuestEN[44078] = { title = "Supporting Cast", description = "", objectives = "" }
WordHunterWoW_QuestEN[44079] = { title = "Druids of the Scythe - 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[44080] = { title = "Friend of the Animals", description = "", objectives = "" }
WordHunterWoW_QuestEN[44081] = { title = "Treacherous Leyrunners", description = "", objectives = "" }
WordHunterWoW_QuestEN[44082] = { title = "Knights of the Ebon Blade", description = "Korgaz Deadaxe has arrived at Acherus to aid us in recruiting additional death knights. He has an eye for potential.\n\nI cannot emphasize enough that it is of the utmost importance that we replenish our numbers during the battle with the Burning Legion.\n\nThe demon armies are nearly endless and we are few.\n\nSpeak with Korgaz when you are ready to recruit additional death knights.", objectives = "Speak to Korgaz Deadaxe.", completion = "Greetings, Deathlord. It is an honor to serve you.\n\nI have been keeping an eye on the casualties of the Alliance and Horde upon the battlefield. Supply is limited, but there are some very promising prospects..." }
WordHunterWoW_QuestEN[44083] = { title = "The Grimoire of the First Necrolyte", description = "This ancient tome appears to be the spellbook of Sataiel, the first necrolyte.\n\nWithin its pages of curses and cantrips, you discover instructions for a ritual that Sataiel was concocting to empower Ulthalesh, the Deadwind Harvester. She calls this ritual, \"The Rite of the Executioner.\"\n\nThe site was chosen and prepared, but Sataiel met her unfortunate end before she could proceed.  Perhaps you can pick up where she left off?\n\nFirst, you'll need some skulls.", objectives = "Collect 13 Skulls of the Executed from powerful humanoid champions throughout Broken Isles, and bring them to the Executioner's Altar in the crypt near Morgan's Plot in Deadwind Pass.", progress = "There's just enough room on the altar for the bounty of skulls you've collected.", completion = "The altar is coated with hundreds of years of dust, but the candles somehow still glow in the distance.\n\nThis must be the site for the ritual." }
WordHunterWoW_QuestEN[44084] = { title = "Vengeance for Margaux", description = "<Sylverin sputters, pale-faced with rage.>\n\nHow could they? Margaux did everything they asked of her and more! The arcwine never stopped flowing despite everything they did to us! To her!\n\nSuch injustice cannot stand. We must take vengeance for Margaux.", objectives = "Slay 8 Vineyard Enforcers or Wardens.", completion = "<Thalyssra is speechless for a moment.>" }
WordHunterWoW_QuestEN[44085] = { title = "Affliction Chosen", description = "", objectives = "" }
WordHunterWoW_QuestEN[44086] = { title = "Destruction Chosen", description = "", objectives = "" }
WordHunterWoW_QuestEN[44087] = { title = "Return to the Fel Hammer", description = "{name}, Battlelord Gaardoun asked me to retrieve you. He says there is a very important matter that he needs your help with.\n\nHe requests your presence back on the Fel Hammer as soon as possible.", objectives = "Speak with Battlelord Gaardoun on the Fel Hammer.", completion = "Commander. I am glad to see that Asha was able to find you so quickly.\n\nThere is something important that you must attend to as soon as possible." }
WordHunterWoW_QuestEN[44088] = { title = "Demonology Chosen", description = "", objectives = "" }
WordHunterWoW_QuestEN[44089] = { title = "A Greater Arsenal", description = "The tome speaks of one more weapon that friend can use against our foes. \n\nDo you wish to seek it?", objectives = "Speak with Calydus to choose to pursue your final artifact.", progress = "Have you made your choice?", completion = "Friend is very wise! You can never have too many weapons!" }
WordHunterWoW_QuestEN[44090] = { title = "Pledge of Loyalty", description = "The eagle appears to have a message for you:\n\nTo: {name}\n\nI hope this message finds you well.\n\nWord of Ohn'ahra's omen has traveled fast. There are many who wish to pledge their loyalty to the Unseen Path's new leader.\n\nReturn to me at Trueshot Lodge, and we can discuss this further.\n\n             -Altar Keeper Biehn", objectives = "Return to Altar Keeper Biehn in Trueshot Lodge.", completion = "I see you received my message." }
WordHunterWoW_QuestEN[44091] = { title = "Needs of the Many", description = "You've seen that the Legion is everywhere. Even with the Illidari as your allies, we are at a great disadvantage.\n\nWe need an edge against the Legion... something to send them back to the Nether.\n\nWe have heard that Dalaran will be the focal point of our campaign. I suggest you go there. You must do anything necessary to become stronger. ANYTHING.\n\nI have seen Kirin Tor mages near Grommash Hold. They can send you to Dalaran.\n\nGo. Take revenge upon the Legion!You will receive:", objectives = "Seek out the Kirin Tor mages in Orgrimmar and travel to Dalaran." }
WordHunterWoW_QuestEN[44092] = { title = "Protect the Home Front", description = "The Legion hasn't just invaded this city. Their evil is spreading across Azeroth, threatening the far corners of our world.\n\nWe must seek them out and stop them, everywhere their darkness touches.\n\nWe've dispatched scouts around the world to watch for Legion activity. As invasions arise, we'll mark the locations on your map.\n\nMake them suffer, {name}!", objectives = "Open your map to find an active Legion invasion in Kalimdor or Eastern Kingdoms. Go to the invasion site and stop the demons!", progress = "Find them! Stop them! Suffer well!", completion = "You've done it! You've broken an invasion!\n\nIf only that had ended our campaign. But the Legion will never relent until they are destroyed... or have destroyed us.\n\nDon't let up! Fight off more of these wretched invasions, <name>. The wyrmtongue we're holding captive here will reward your efforts." }
